// BEGIN_MP4_SHADER_LEASE_HOST
using Mp4ShaderSet=void(*)(float,Method*);
using Mp4ShaderReset=void(*)(Method*);
Mp4ShaderSet mp4_shader_set_original=nullptr;
Mp4ShaderReset mp4_shader_reset_original=nullptr;
pthread_mutex_t mp4_shader_mutex=PTHREAD_MUTEX_INITIALIZER;
uint64_t mp4_shader_generation=1;
struct Mp4ShaderLease {
    void* context=nullptr;uint64_t generation=0;bool active=false,custom=false;float previous=0;
    uint64_t serial=0;float owned_time=0;bool have_owned_time=false;unsigned suspended=0;
} mp4_shader_lease;
uint64_t mp4_shader_next_lease=0;
struct Mp4ShaderSuspension {void* context=nullptr;uint64_t generation=0,serial=0;unsigned depth=0;bool active=false;};
struct Mp4ShaderLock {
    Mp4ShaderLock(){pthread_mutex_lock(&mp4_shader_mutex);}
    ~Mp4ShaderLock(){pthread_mutex_unlock(&mp4_shader_mutex);}
};
void mp4_shader_external_write(){
    if(mp4_shader_generation)mp4_shader_generation=mp4_shader_generation==~uint64_t(0)?0:mp4_shader_generation+1;
}
void mp4_shader_set_hook(float seconds,Method* method){
    // Both original setters contain only IL2CPP initialization and one static
    // float write. Their original .cctor also only initializes that float;
    // there is no callback/reentrant setter while this lock is held.
    Mp4ShaderLock lock;mp4_shader_external_write();mp4_shader_set_original(seconds,method);
}
void mp4_shader_reset_hook(Method* method){
    Mp4ShaderLock lock;mp4_shader_external_write();mp4_shader_reset_original(method);
}
bool mp4_shader_lease_begin(void* context){
    if(!context||!game_call()||!mp4_source_verified||!mp4_api_installed
        ||!mp4_shader_set_original||!mp4_shader_reset_original
        ||!mp4_api.shader_use_custom||!mp4_api.shader_current_time)return false;
    Mp4ShaderLock lock;
    if(mp4_shader_lease.active||!mp4_shader_generation||mp4_shader_next_lease==~uint64_t(0))return false;
    const bool custom=mp4_api.shader_use_custom(nullptr);const float previous=mp4_api.shader_current_time(nullptr);
    if(!std::isfinite(previous))return false;
    mp4_shader_lease={context,mp4_shader_generation,true,custom,previous};
    mp4_shader_lease.serial=++mp4_shader_next_lease;return true;
}
bool mp4_shader_lease_set_time(void* context,float seconds){
    if(!std::isfinite(seconds)||seconds<0||seconds>900)return false;
    Mp4ShaderLock lock;
    if(!mp4_shader_lease.active||context!=mp4_shader_lease.context
        ||mp4_shader_lease.suspended||!mp4_shader_generation||mp4_shader_lease.generation!=mp4_shader_generation)return false;
    // Bypass our external-write hooks. Compare and raw apply are serialized
    // against every normal Set/Reset, including same-value external writes.
    mp4_shader_set_original(seconds,nullptr);mp4_shader_lease.owned_time=seconds;mp4_shader_lease.have_owned_time=true;return true;
}
[[maybe_unused]] bool mp4_shader_suspend_for_unowned(Mp4ShaderSuspension& token){
    if(token.active||!game_call())return false;
    Mp4ShaderLock lock;auto& lease=mp4_shader_lease;
    if(!lease.active||!lease.have_owned_time)return true;
    if(lease.generation!=mp4_shader_generation||lease.suspended==16)return false;
    if(!lease.suspended){
        if(!mp4_api.shader_use_custom||!mp4_api.shader_current_time||!mp4_api.shader_use_custom(nullptr)
            ||mp4_api.shader_current_time(nullptr)!=lease.owned_time)return false;
        if(lease.custom)mp4_shader_set_original(lease.previous,nullptr);else mp4_shader_reset_original(nullptr);
    }
    token={lease.context,lease.generation,lease.serial,++lease.suspended,true};return true;
}
[[maybe_unused]] bool mp4_shader_resume_after_unowned(Mp4ShaderSuspension& token){
    if(!token.active)return false;
    Mp4ShaderLock lock;auto& lease=mp4_shader_lease;token.active=false;
    if(!lease.active||lease.context!=token.context||lease.serial!=token.serial
        ||lease.generation!=token.generation||mp4_shader_generation!=token.generation)return false;
    if(lease.suspended!=token.depth||!mp4_api.shader_use_custom||!mp4_api.shader_current_time
        ||mp4_api.shader_use_custom(nullptr)!=lease.custom
        ||(lease.custom&&mp4_api.shader_current_time(nullptr)!=lease.previous)){
        // Never rewind a superseding ambient owner or an unbalanced frame.
        mp4_shader_external_write();return false;
    }
    if(!--lease.suspended)mp4_shader_set_original(lease.owned_time,nullptr);
    return true;
}
void mp4_shader_lease_finish(void* context){
    Mp4ShaderLock lock;
    if(!mp4_shader_lease.active||context!=mp4_shader_lease.context)return;
    const auto saved=mp4_shader_lease;mp4_shader_lease={};
    if(saved.generation!=mp4_shader_generation||!mp4_shader_generation)return;
    // Global saved state only: safe after a selected MV was replaced. A new
    // external owner always wins, even if its value equals our last value.
    if(saved.custom)mp4_shader_set_original(saved.previous,nullptr);
    else mp4_shader_reset_original(nullptr);
}
void mp4_shader_lease_abandon(void* context) noexcept {
    // The caller has already recognized a failed handoff of this exact
    // playback context. Forget our rollback duty without running a setter.
    Mp4ShaderLock lock;
    if(mp4_shader_lease.active&&mp4_shader_lease.context==context)mp4_shader_lease={};
}
[[maybe_unused]] idoly_mp4_playback::ShaderLeaseApi mp4_shader_lease_api(){
    return {mp4_shader_lease_begin,mp4_shader_lease_set_time,mp4_shader_lease_finish};
}
// END_MP4_SHADER_LEASE_HOST

// BEGIN_MP4_HOOK_BOOTSTRAP_CORE
#ifndef IDOLY_DARWIN_BRIDGE
#include <stdint.h>
#include <stddef.h>
#include <string.h>
#include <atomic>
#endif
// Source-code binding only. This bank grants no graph/output/callback
// authority.
namespace mp4_bootstrap {
enum class BootstrapRole : uint8_t {
  enqueue,
  append_a,
  append_b,
  collect,
  deferred_a,
  deferred_b,
  graph_create,
  factory
};
enum class BootstrapImage : uint8_t { engine, game };
struct BootstrapPin {
  BootstrapRole role;
  BootstrapImage image;
  uintptr_t rva;
  uint8_t original[24];
};
struct Source {
  uintptr_t base = 0;
  uint64_t load = 0, cohort = 0;
};
struct Bytes {
  uintptr_t address = 0;
  uint8_t data[192]{};
  size_t count = 0;
};
struct Install {
  uintptr_t target = 0, replacement = 0, gateway = 0, stub = 0;
  uint64_t serial = 0;
  uint8_t original[24]{}, patch[24]{};
  size_t span = 0;
  Bytes enter{}, island_exit{}, island_enter{};
  uintptr_t resume = 0;
};
struct Api {
  void *context = nullptr;
  bool (*installer_thread)(void *) = nullptr;
  // Actual loaded module/cohort certificate; base plus loader generation and
  // completed original-source verification, not string equality of hashes.
  bool (*source)(void *, BootstrapImage, Source *) = nullptr;
  bool (*read_code)(void *, uintptr_t, void *, size_t) = nullptr;
  // Real backend install transaction. Android: exact UNIQUE Shadowhook trace
  // matching target/new/stub, actual copied original and enter/island bytes.
  // iOS: exact compiled native relay/source patch plan plus live publication.
  bool (*installed)(void *, BootstrapRole, uintptr_t, uintptr_t, uintptr_t,
                    uintptr_t, Install *) = nullptr;
  // Finite source relocation equivalence, not just an executable address. The
  // Android helper validates the exact v2.0.1 trace/code; iOS uses its
  // generated original-relay bytes/branch targets and exact own static
  // installer record.
  bool (*gateway_source)(void *, const BootstrapPin &,
                         const Install &) = nullptr;
  // Read-only actual own table equality; no allocation, native invocation or
  // World.validate recursion. Revoke this before any owned unhook/replacement.
  bool (*publication)(void *, BootstrapRole, const Install &) = nullptr;
};
struct Ticket {
  uint8_t index = 0;
  uint64_t serial = 0;
};
class Bank {
  struct Entry {
    BootstrapPin pin{};
    uintptr_t replacement = 0;
    Source source{};
    uint64_t preparing = 0;
    Install install{};
    bool published = false;
  };
  Entry entries_[8]{};
  Api api_{};
  uint64_t sequence_ = 0;
  bool configured_ = false;
  static bool same(Source a, Source b) {
    return a.base == b.base && a.load == b.load && a.cohort == b.cohort;
  }
  bool source(const Entry &e) const {
    Source now{};
    return api_.source(api_.context, e.pin.image, &now) && now.base &&
           now.load && now.cohort && same(e.source, now);
  }
  bool bytes(const Bytes &b) const {
    uint8_t now[192]{};
    return b.address && b.count && b.count <= sizeof now &&
           api_.read_code(api_.context, b.address, now, b.count) &&
           !::memcmp(now, b.data, b.count);
  }

public:
  bool configure(Api api, const BootstrapPin *pins,
                 const uintptr_t *replacements) {
    if (configured_ || !pins || !replacements || !api.installer_thread ||
        !api.source || !api.read_code || !api.installed ||
        !api.gateway_source || !api.publication)
      return false;
    for (size_t i = 0; i < 8; ++i) {
      if (static_cast<size_t>(pins[i].role) != i ||
          pins[i].image !=
              (i == 7 ? BootstrapImage::game : BootstrapImage::engine) ||
          !pins[i].rva || !replacements[i])
        return false;
      entries_[i].pin = pins[i];
      entries_[i].replacement = replacements[i];
    }
    api_ = api;
    configured_ = true;
    return true;
  }
  bool begin(BootstrapRole role, Ticket *out) {
    if (out)
      *out = {};
    const size_t i = static_cast<size_t>(role);
    if (!out || !configured_ || i >= 8 ||
        !api_.installer_thread(api_.context) || sequence_ == ~uint64_t(0))
      return false;
    auto &e = entries_[i];
    if (e.preparing || e.published)
      return false;
    Source now{};
    uint8_t current[24]{};
    if (!api_.source(api_.context, e.pin.image, &now) || !now.base ||
        !now.load || !now.cohort || e.pin.rva > ~uintptr_t(0) - now.base ||
        !api_.read_code(api_.context, now.base + e.pin.rva, current, 24) ||
        ::memcmp(current, e.pin.original, 24))
      return false;
    e.source = now;
    e.preparing = ++sequence_;
    *out = {static_cast<uint8_t>(i), e.preparing};
    return true;
  }
  bool publish(Ticket ticket, uintptr_t gateway, uintptr_t stub) {
    if (!configured_ || ticket.index >= 8 || !ticket.serial || !gateway ||
        !stub || !api_.installer_thread(api_.context))
      return false;
    auto &e = entries_[ticket.index];
    if (e.preparing != ticket.serial || e.published || !source(e))
      return false;
    Install actual{};
    if (!api_.installed(api_.context, e.pin.role, e.source.base + e.pin.rva,
                        e.replacement, gateway, stub, &actual) ||
        actual.target != e.source.base + e.pin.rva ||
        actual.replacement != e.replacement || actual.gateway != gateway ||
        actual.stub != stub || !actual.serial ||
        (actual.span != 4 && actual.span != 16 && actual.span != 20 &&
         actual.span != 24) ||
        ::memcmp(actual.original, e.pin.original, actual.span) ||
        actual.enter.address != gateway || !actual.enter.count ||
        !bytes(actual.enter) ||
        (actual.island_exit.address && !bytes(actual.island_exit)) ||
        (actual.island_enter.address && !bytes(actual.island_enter)) ||
        !api_.gateway_source(api_.context, e.pin, actual) ||
        !api_.publication(api_.context, e.pin.role, actual))
      return false;
    uint8_t now[24]{};
    if (!api_.read_code(api_.context, actual.target, now, 24) ||
        ::memcmp(now, actual.patch, actual.span) ||
        (actual.span < 24 &&
         ::memcmp(now + actual.span, e.pin.original + actual.span,
                  24 - actual.span)) ||
        !source(e))
      return false;
    e.install = actual;
    e.preparing = 0;
    e.published = true;
    return true;
  }
  bool current(BootstrapRole role, uintptr_t typed_original = 0) const {
    const size_t i = static_cast<size_t>(role);
    if (!configured_ || i >= 8)
      return false;
    const auto &e = entries_[i];
    const auto &r = e.install;
    if (!e.published || !source(e) ||
        (typed_original && typed_original != r.gateway) ||
        !api_.publication(api_.context, role, r))
      return false;
    uint8_t now[24]{};
    return api_.read_code(api_.context, r.target, now, 24) &&
           !::memcmp(now, r.patch, r.span) &&
           (r.span == 24 ||
            !::memcmp(now + r.span, e.pin.original + r.span, 24 - r.span)) &&
           bytes(r.enter) && (!r.island_exit.address || bytes(r.island_exit)) &&
           (!r.island_enter.address || bytes(r.island_enter));
  }
  bool native_code(uintptr_t rva, const uint8_t prefix[16]) const {
    if (!configured_ || !prefix)
      return false;
    for (size_t i = 0; i < 7; ++i) {
      const auto &e = entries_[i];
      if (e.pin.image == BootstrapImage::engine && e.pin.rva == rva &&
          !::memcmp(e.pin.original, prefix, 16))
        return current(e.pin.role);
    }
    return false;
  }
  void revoke(BootstrapRole role) noexcept {
    const size_t i = static_cast<size_t>(role);
    if (i < 8) {
      entries_[i].published = false;
      entries_[i].preparing = 0;
    }
  }
};
} // namespace mp4_bootstrap

