uint64_t mp4_volume_original_evaluate_epoch=0;
unsigned mp4_volume_original_evaluate_depth=0;
// Scalar stack receipt for actual original calls, distinct from pending graph
// bookkeeping and from a queued operation's own journal serial.
struct Mp4RawOriginalOperation {
    uint64_t epoch=0,serial=0,receipt=0;
    uintptr_t root_asset=0,director=0,method=0;
    uint8_t kind=0;unsigned depth=0;bool invoked=false;
} mp4_raw_original_operation;
uint64_t mp4_raw_original_sequence=0,mp4_raw_evaluate_sequence=0;
void* mp4_scene_root_asset_receipt(uint64_t);
bool mp4_native_phase_origin(uint64_t,void*,uintptr_t);
struct Mp4OriginalOperationScope {
    Mp4RawOriginalOperation previous=mp4_raw_original_operation;
    bool valid=false;
    Mp4OriginalOperationScope(uint64_t epoch,uint8_t kind,void* director,uintptr_t method,uint64_t receipt){
        void* asset=mp4_scene_root_asset_receipt(epoch);
        if(!epoch||!asset||!director||!method||mp4_raw_original_sequence==~uint64_t(0)
            ||previous.depth>=8||kind<1||kind>7||(kind==3&&!receipt)
            ||(kind==7&&(previous.depth||!mp4_native_phase_origin(epoch,director,method))))return;
        if(!receipt){if(mp4_raw_evaluate_sequence==~uint64_t(0))return;receipt=++mp4_raw_evaluate_sequence;}
        mp4_raw_original_operation={epoch,++mp4_raw_original_sequence,receipt,
            reinterpret_cast<uintptr_t>(asset),reinterpret_cast<uintptr_t>(director),method,kind,previous.depth+1,false};
        valid=true;
    }
    void invoked(){if(valid)mp4_raw_original_operation.invoked=true;}
    ~Mp4OriginalOperationScope(){if(valid)mp4_raw_original_operation=previous;}
};
struct Mp4OriginalEvaluationScope {
    uint64_t previous=mp4_volume_original_evaluate_epoch;
    Mp4OriginalOperationScope operation;
    Mp4OriginalEvaluationScope(uint64_t epoch,void*director,bool restoring)
        :operation(epoch,restoring?5:4,director,reinterpret_cast<uintptr_t>(mp4_api.director_evaluate),0){
        mp4_volume_original_evaluate_epoch=epoch;++mp4_volume_original_evaluate_depth;
    }
    ~Mp4OriginalEvaluationScope(){--mp4_volume_original_evaluate_depth;mp4_volume_original_evaluate_epoch=previous;}
};
mp4actor::Result mp4_actor_zero_pose(void*){
    if(!mp4_actor_selected_source(nullptr)||!mp4_actor_host.director)return mp4actor::Result::stale;
    if(!mp4_actor_clock_held(nullptr))return mp4actor::Result::waiting;
    if(!mp4_stage_refresh_controls())return mp4actor::Result::stale;
    mp4_api.director_set_time(mp4_actor_host.director,0,nullptr);
    if(!mp4_actor_selected_source(nullptr))return mp4actor::Result::stale;
    if(!mp4_stage_begin_zero_evaluation())return mp4actor::Result::stale;
    struct ZeroEvaluationExit{~ZeroEvaluationExit(){mp4_stage_end_zero_evaluation();}} zero_exit;
    if(!mp4_scene_evaluate_receipt_begin(mp4_actor_host.director))return mp4actor::Result::stale;
    bool maps_ok=false;
    bool audio_ok=false;
    if(!mp4_actor_mono_gate.isolate([&]{Mp4OriginalEvaluationScope receipt(mp4_actor_host.epoch,mp4_actor_host.director,false);
            if(!receipt.operation.valid||!mp4_audio_outer_evaluation_begin(mp4_actor_host.director,false))return;
            receipt.operation.invoked();
            mp4_api.director_evaluate(mp4_actor_host.director,nullptr);
            audio_ok=mp4_audio_outer_evaluation_completed(mp4_actor_host.director);maps_ok=mp4_actor_refresh_maps();})
        ||!audio_ok||!maps_ok||!mp4_scene_timeline_receipt_observe(true)
        ||!mp4_audio_outer_after_original_evaluate(false))return mp4actor::Result::stale;
    if(!mp4_actor_selected_source(nullptr))return mp4actor::Result::stale;
    const double time=mp4_actor_root_time(nullptr);
    return std::isfinite(time)&&std::fabs(time)<=.0001?mp4actor::Result::ok:mp4actor::Result::failed;
}
