    // Resource retirement must never recompute it after ordinary MV progress.
    host.pending_camera_restore=host.parts[1].restoration_verified(host.parts[1].context);
    host.pending_dependency_restore=host.parts[0].restoration_verified(host.parts[0].context)
        &&host.parts[2].restoration_verified(host.parts[2].context)&&host.parts[3].restoration_verified(host.parts[3].context);
    host.logical_checkpoint=host.pending_camera_restore&&host.pending_dependency_restore;
