    m.slot_image=s.images.block_new();if(!m.slot_image||!mp4_equipment_pin(m.slot_image,true))return false;
    s.images.block_get(renderer,m.slot_image,0,nullptr);m.empty=s.images.block_empty(m.slot_image,nullptr);
