    const auto gl=mp4_gpu_gl_preflight_for(h,source,epoch);if(gl!=Mp4SceneResult::ok)return gl;
#endif
    if(!h.configured&&!mp4_gpu_host_configure_for(h,source,epoch,recipe))return Mp4SceneResult::unsupported;
    if(!mp4_gpu_host_sources(&h,mp4_gpu_pins)||h.sequence==~uint64_t(0)
        ||mp4_gpu_auxiliary_serial==~uint64_t(0)||!h.ledger.begin_auxiliary(epoch,h.sequence+1))return Mp4SceneResult::stale;
