// Pointer-only global owner: expanded Source snapshots live on the heap after
// the first actual capture. The stable bank is intentionally process-lifetime;
// clear() releases retained managed roots, never invokes Unity from a static
// destructor, and never creates a multi-megabyte temporary on a Unity stack.
class Mp4LazySourceVolumeScope {
  mp4vs::Scope *scope_=nullptr;
public:
  Mp4LazySourceVolumeScope()=default;
  Mp4LazySourceVolumeScope(const Mp4LazySourceVolumeScope&)=delete;
  Mp4LazySourceVolumeScope&operator=(const Mp4LazySourceVolumeScope&)=delete;
  bool allocated()const noexcept{return scope_!=nullptr;}
  mp4vs::Result capture(mp4vs::Api api,void*context){
    if(!scope_){
      void*memory=::malloc(sizeof(mp4vs::Scope));
      if(!memory)return mp4vs::Result::unsupported;
      scope_=new(idoly_mp4_actor_placement::Address{memory})mp4vs::Scope{};
    }
    return scope_->capture(api,context);
  }
  void clear(){if(scope_)scope_->clear();}
  const char*error()const{return scope_?scope_->error():"volume_source_heap_unallocated";}
  bool owns_volume(void*object)const{return scope_&&scope_->owns_volume(object);}
  bool captured_image(void*object,mp4vs::CapturedVolumeImage*out){if(out)*out={};return scope_&&scope_->captured_image(object,out);}
  uint64_t capture_receipt_raw()const noexcept{return scope_?scope_->capture_receipt_raw():0;}
  mp4vs::Result validate(){return scope_?scope_->validate():mp4vs::Result::invalid;}
  mp4vs::Result validate_inputs(){return scope_?scope_->validate_inputs():mp4vs::Result::invalid;}
  mp4vs::Result restore(){return scope_?scope_->restore():mp4vs::Result::invalid;}
  mp4vs::Result verify(){return scope_?scope_->verify():mp4vs::Result::invalid;}
};
static_assert(sizeof(Mp4LazySourceVolumeScope)==sizeof(void*),"Source global must remain pointer-only");

