// BEGIN_MP4_SCENE_DIAGNOSTIC_HOST
// This observer runs admission without configuring an export. Its temporary
// ledger lets later families test the same measured source; it cannot register
// parts, install NativeSceneControl, acquire the clock, or publish a grant.
void mp4_scene_diagnostic_parts(const Mp4SceneWitness& witness,const Mp4ScenePart (&parts)[4],
    const bool (&verified)[4],idoly_mp4_runtime::NativeSceneDiagnostics& output){
    auto& host=mp4_scene_host;
    struct Ledger {
        Mp4SceneHost& host;unsigned admitted;Mp4SceneWitness source;
        ~Ledger(){mp4_stage_admission_drop();host.admitted=admitted;host.admitted_source=source;}
    } ledger{host,host.admitted,host.admitted_source};
    mp4_stage_admission_drop();
    host.admitted=0;host.admitted_source=witness;output.available=true;
    for(unsigned i=0;i<4;++i){
        auto& part=output.parts[i];
        if(!verified[i]){
            part.result=static_cast<int32_t>(Mp4SceneResult::unsupported);
            snprintf(part.error,sizeof(part.error),"%s","diagnostic_source_bindings_unverified");
            continue;
        }
        try {
            const auto result=parts[i].admit(parts[i].context,witness);
            part.result=static_cast<int32_t>(result);
            const char* error=result==Mp4SceneResult::ok?"none":parts[i].error(parts[i].context);
            snprintf(part.error,sizeof(part.error),"%s",error&&error[0]&&(result==Mp4SceneResult::ok||std::strcmp(error,"none"))?error:"diagnostic_admission_failed");
            if(result==Mp4SceneResult::ok)host.admitted|=1u<<i;
        }catch(...){
            part.result=static_cast<int32_t>(Mp4SceneResult::failed);
            snprintf(part.error,sizeof(part.error),"%s","diagnostic_admission_exception");
        }
        Mp4SceneWitness current{};
        if(!idoly_mp4_runtime::game.selected_scene_witness(current)||!mp4_scene_same_source(witness,current)){
            for(unsigned j=i;j<4;++j){output.parts[j].result=static_cast<int32_t>(Mp4SceneResult::stale);
                snprintf(output.parts[j].error,sizeof(output.parts[j].error),"%s","diagnostic_source_changed");}
            return;
        }
    }
}
void mp4_scene_diagnostic_probe(void*,idoly_mp4_runtime::NativeSceneDiagnostics* output){
    if(!output)return;
    *output={};
    if(!game_call()||mp4_scene_host.active||mp4_actor_host.scope.active()
        ||mp4_camera_host.scope.active()||mp4_stage_host.configured||mp4_world_host.scope.active()){
        for(auto& part:output->parts)snprintf(part.error,sizeof(part.error),"%s","diagnostic_source_busy");
        return;
    }
    Mp4SceneWitness witness{};
    if(!idoly_mp4_runtime::game.selected_scene_witness(witness)){
        for(auto& part:output->parts)snprintf(part.error,sizeof(part.error),"%s","diagnostic_source_not_ready");
        return;
    }
    if(!mp4_actor_source_verified)mp4_verify_actor_calls();
    if(mp4_actor_source_verified)(void)mp4_prepare_actor_types();
    if(!mp4_stage_source_verified)mp4_verify_stage_calls();
    if(!mp4_camera_host.verified)(void)mp4_verify_camera_calls();
    if(!mp4_world_host.verified)(void)mp4_verify_world_calls();
    const Mp4ScenePart parts[4]={mp4_scene_actor_part(),mp4_scene_camera_part(),mp4_stage_part(),mp4_scene_world_part()};
    const bool verified[4]={mp4_actor_source_verified,mp4_camera_host.verified,mp4_stage_source_verified,mp4_world_host.verified};
    mp4_scene_diagnostic_parts(witness,parts,verified,*output);
}
// END_MP4_SCENE_DIAGNOSTIC_HOST

bool mp4_camera_permit_brain(void* brain){
    if(!mp4_fresh_permit_brain(brain))return false;
    if(!mp4_camera_interception_published()||!game_call()||!mp4_camera_host.scope.active())return true;
    return mp4_camera_host.scope.permit_brain_update(brain);
}
// BEGIN_MP4_CAMERA_OUTPUT_CAPABILITIES
// Read-only finite producer capability. A current, authorized camera graph
// proves ownership of a rebuilt temporary mixer too; requiring the old source
// mixer's object address would reject the mandatory fresh-graph transaction.
// No TimelinePlayable/unknown-script/state family is admitted by this ledger.
bool mp4_camera_script_producer_owned(void* script){
    auto& host=mp4_camera_host;
    if(!script||!host.verified||host.invalidated||!mp4_camera_source_current(nullptr))return false;
    const auto* schema=mp4_camera_schema(object_class(script));if(!schema)return false;
    if(mp4_exact_type(script,".CinemachineShotPlayable")){
        void* camera=nullptr;
        return mp4_actor_field(script,mp4camp::ExtraLayout::shot_camera,camera)
            &&mp4_camera_in(camera,host.cameras,host.camera_count)&&mp4_alive(camera);
    }
    if(mp4_exact_type(script,".CinemachineMixer")){
        void* brain=nullptr;int32_t id=-2;
        if(!mp4_actor_field(script,mp4camp::Layout::mixer_brain,brain)
            ||!mp4_actor_field(script,mp4camp::Layout::mixer_id,id))return false;
        // Before the authorized first Evaluate the fresh original mixer has
        // not acquired its Brain override; its original sentinel is -1/null.
        return (!brain&&id==-1)||(brain==host.source.brain&&id>=0);
    }
    return false;
}
[[maybe_unused]] bool mp4_camera_owns_playable_handle(mp4actor::Handle wanted){
    if(!wanted.handle||!mp4_camera_source_current(nullptr))return false;
    Mp4CameraGraphNode nodes[512]{};size_t count=0;
    if(!mp4_camera_graph_nodes(nodes,512,&count))return false;
    using Script=void*(*)(mp4actor::Handle*,Method*);
    for(size_t i=0;i<count;++i)if(nodes[i].handle.handle==wanted.handle&&nodes[i].handle.version==wanted.version){
        void* script=mp4_cam_call<Script>(mp4_cam_profile.playable_script)(&nodes[i].handle,nullptr);
        return mp4_camera_script_producer_owned(script);
    }
    return false;
}
[[maybe_unused]] bool mp4_camera_owns_script_userdata(void* value){
    auto& host=mp4_camera_host;if(!value)return true;
    if(!host.verified||host.invalidated||!mp4_camera_source_current(nullptr))return false;
    // Brain is already a separately captured native-component/cache owner.
    if(value==host.source.brain)return true;
    if(!mp4_camera_script_producer_owned(value))return false;
    Mp4CameraGraphNode nodes[512]{};size_t count=0;
    if(!mp4_camera_graph_nodes(nodes,512,&count))return false;
    using Script=void*(*)(mp4actor::Handle*,Method*);
    for(size_t i=0;i<count;++i)
        if(mp4_cam_call<Script>(mp4_cam_profile.playable_script)(&nodes[i].handle,nullptr)==value)return true;
    return false;
}

// END_MP4_CAMERA_OUTPUT_CAPABILITIES
// BEGIN_MP4_DIRECTOR_MAINTENANCE_CORE
// Shared-only: embed in the existing engine/bridge inputs. Requires the actual
// idoly_mp4_world DirectorPending/Authorization types from mp4_engine_clock.hpp.
namespace mp4_director_maintenance {
namespace world=idoly_mp4_world;
enum class Kind:uint8_t {play=1,stop=2,rebuild=3,zero_evaluate=4,saved_evaluate=5,maintenance=6,native_phase=7};
enum class Hook:uint8_t {enqueue=1,append_a=2,append_b=3,collect=4,deferred_a=5,deferred_b=6};
struct Call {
 Kind kind=Kind::play;
 uint64_t epoch=0,serial=0;
 uintptr_t source_asset=0,receiver=0,method=0;
 uint64_t original_receipt=0;
};
// A successful source module capture BEFORE the original operation while its
// handles/outputs were live; a type/hash/address match is insufficient.
struct Basis {
 world::DirectorGraphIdentity graph{};
 uint64_t epoch=0,producer_receipt=0,callback_receipt=0,output_receipt=0;
 uintptr_t source_asset=0;
};
struct Provisional {
 world::DirectorGraphIdentity graph{};
 uint64_t epoch=0,original_receipt=0,birth_receipt=0,factory_receipt=0,operation_serial=0;
 uintptr_t source_asset=0;
};
struct Api {
 void*context=nullptr;
 uintptr_t manager=0;
 bool tagged_queue=false;
 bool(*current)(void*,const Call&)=nullptr;
 bool(*call_origin)(void*,const Call&)=nullptr;
 bool(*retired_output)(void*,uint64_t,uintptr_t,uintptr_t,uint32_t,uint64_t,uintptr_t)=nullptr;
 bool(*read)(void*,uintptr_t,void*,size_t)=nullptr;
 // Actual installed native-hook TLS + source-prefix/gateway receipt. Must also
 // exclude unrelated threads/producers for this bounded original call.
 bool(*hook_origin)(void*,Hook,uintptr_t,const Call&)=nullptr;
 bool(*basis)(void*,const Call&,world::AnimationGraph,uint32_t,Basis*)=nullptr;
 // Typed source producer/callback recipes cover all in-loop future appends,
 // and all potentially concurrent producer jobs are physically fenced.
 bool(*future_producers_closed)(void*,const Call&)=nullptr;
 // Optional as a COMPLETE triple. Real source-created, actual factory-bound
 // Play0 may be recorded unconsumed; full callback/output closure is still owed.
 bool(*provisional_play)(void*,const Call&,world::AnimationGraph,Provisional*)=nullptr;
 bool(*provisional_current)(void*,const Provisional&)=nullptr;
 world::Result(*promote)(void*,const Call&,const Provisional&,Basis*)=nullptr;
 // Actual accepted native phase5 original-stack witness for this SAME Kind7
 // Call/serial/method/tick. Optional for legacy held-only service; NULL can
 // never authorize frame deferred consumption.
 bool(*frame_deferred_current)(void*,const Call&)=nullptr;

};
struct Ticket {uint64_t call=0,sequence=0;
Hook hook=Hook::enqueue;
};
class Journal {
 static constexpr size_t limit=512;
 struct Item {uintptr_t address=0,next=0;
 world::AnimationGraph handle{};
 uint32_t operation=0;
 };
 struct View {uintptr_t queue=0,head=0;
 uint64_t tag=0;
 size_t count=0;
 Item item[limit]{};
 };
 struct Receipt {Item item{};
 Basis basis{};
 Call origin{};
 Provisional promise{};
 uint64_t serial=0;
 Kind kind=Kind::play;
 uint64_t original_receipt=0;
 bool live=false,provisional=false;
 };
 Api api_{};
 Call call_{};
 bool configured_=false,active_=false,invoked_=false,failed_=false;
 bool native_=false,collect_=false,publication_waiting_=false;
 uint64_t sequence_=0,last_call_=0;
 Ticket native_ticket_{};
 world::AnimationGraph requested_{};
 uint32_t requested_operation_=0;
 Basis requested_basis_{};
 Provisional requested_promise_{};
 View before_{},after_{};
 Receipt receipt_[limit]{};
 size_t receipts_=0;
 const char*error_="none";
 template<class T>bool read(uintptr_t at,T&v)const {
  return at&&at+sizeof(T)>=at&&api_.read(api_.context,at,&v,sizeof(T));
 }
 bool span(uintptr_t p,uint64_t n,size_t stride)const {
  return n<=limit&&n<=(~size_t(0))/stride&&(!n||(p&&p+size_t(n)*stride>=p));
 }
 bool fail(const char*why){failed_=true;
 error_=why;
 return false;
 }
 bool current()const{return configured_&&active_&&!failed_&&api_.current(api_.context,call_);
 }
 bool origin(Hook hook,uintptr_t receiver)const {
  return current()&&api_.hook_origin(api_.context,hook,receiver,call_);
 }
 static bool handle(world::AnimationGraph a,world::AnimationGraph b) {
  return a.handle==b.handle&&(a.version&~uint32_t(1))==(b.version&~uint32_t(1));
 }
 static bool same(const Item&a,const Item&b,bool address=true) {
  return (!address||a.address==b.address)&&a.next==b.next&&handle(a.handle,b.handle)&&a.operation==b.operation;
 }
 bool queue(View&v)const {
  v=View{};
  if(!read(api_.manager+0x478,v.queue)||!v.queue||(v.queue&7)||!read(v.queue,v.head)
   ||(api_.tagged_queue&&!read(v.queue+8,v.tag)))return false;
  uintptr_t at=v.head;
  while(at){
   if(v.count==limit||(at&7))return false;
   for(size_t i=0;i<v.count;++i)if(v.item[i].address==at)return false;
   Item&i=v.item[v.count++];
   i.address=at;
   if(!read(at,i.next)||!read(at+8,i.handle.handle)||!read(at+16,i.handle.version)||!read(at+24,i.operation))return false;
   at=i.next;
  }
  return true;
 }
 bool deferred(unsigned index,View&v)const {
  v=View{};
  const uintptr_t at=api_.manager+(index?0x3a8:0x388);
  uintptr_t data=0;
  uint64_t count=0,capacity=0;
  if(!read(at,data)||!read(at+16,count)||!read(at+24,capacity)||count>(capacity>>1)||!span(data,count,16))return false;
  v.queue=data;
  v.count=size_t(count);
  v.tag=capacity;
  for(size_t k=0;k<v.count;++k){auto&i=v.item[k];
  i.address=data+k*16;
  i.operation=index?8:7;
  if(!read(i.address,i.handle))return false;
  }
  return true;
 }
 // Check only the CURRENT versioned slot; never dereference an invalid old
 // public handle/native graph. Stale records are skipped by original source.
 bool live(world::AnimationGraph h,bool&valid)const {
  valid=false;
  if(!h.handle)return true;
  uint32_t version=0;
  uintptr_t native=0;
  if((h.handle&7)||!read(h.handle+0x20,version))return false;
  if(version!=(h.version&~uint32_t(1)))return true;
  if(!read(h.handle+0x28,native))return false;
  valid=native!=0;
  return true;
 }
 bool basis(world::AnimationGraph h,uint32_t operation,Basis&out)const {
  out=Basis{};
  if(!api_.basis(api_.context,call_,h,operation,&out)||out.epoch!=call_.epoch||!out.producer_receipt
   ||!out.callback_receipt||!out.output_receipt||out.source_asset!=call_.source_asset
   ||out.graph.slot!=h.handle||out.graph.version!=(h.version&~uint32_t(1))||!out.graph.native)return false;
  uint32_t version=0;
  uintptr_t native=0;
  return read(h.handle+0x20,version)&&version==out.graph.version&&read(h.handle+0x28,native)&&native==out.graph.native;
 }
 bool permitted(uint32_t operation)const {
  if(operation>8)return false;
  if(call_.kind==Kind::play)return operation==0;
  if(call_.kind==Kind::stop)return operation==1;
  // Remaining original source transactions may cause finite child graph
  // lifecycle operations. Every event STILL needs its specific Basis receipt.
  return true;
 }
 Receipt*find(const Item&i) {
  for(size_t n=0;n<receipts_;++n){auto&r=receipt_[n];
  if(r.live&&same(r.item,i))return &r;
  }
  return nullptr;
 }
 bool authorized(const Item&i,bool allow_unconsumed=false) {
  bool valid=false;
  if(!live(i.handle,valid))return false;
  if(!valid)return true;
  auto*r=find(i);
  if(!r||!r->serial)return false;
  if(r->provisional){
   if(i.operation!=0||!api_.provisional_current||!api_.promote||!api_.provisional_current(api_.context,r->promise))return false;
   if(allow_unconsumed)return true;
   Basis full{};
   const auto result=api_.promote(api_.context,r->origin,r->promise,&full);
   if(result==world::Result::waiting){publication_waiting_=true;
   return false;
   }
   if(result!=world::Result::ok||!full.producer_receipt||!full.callback_receipt||!full.output_receipt
    ||full.graph.native!=r->promise.graph.native||full.graph.slot!=r->promise.graph.slot
    ||full.graph.version!=r->promise.graph.version||full.epoch!=r->promise.epoch
    ||full.source_asset!=r->promise.source_asset)return false;
   r->basis=full;
   r->provisional=false;
  }
  const auto&b=r->basis;
  uint32_t version=0;
  uintptr_t native=0;
  return b.epoch==call_.epoch&&b.source_asset==call_.source_asset&&b.graph.slot==i.handle.handle
   &&b.graph.version==(i.handle.version&~uint32_t(1))&&read(i.handle.handle+0x20,version)
   &&version==b.graph.version&&read(i.handle.handle+0x28,native)&&native==b.graph.native;
 }
 bool all(const View&v,bool allow_unconsumed=false) {
  bool waiting=false,unsupported=false;
  for(size_t i=0;i<v.count;++i){
   publication_waiting_=false;
   if(!authorized(v.item[i],allow_unconsumed)){
    if(publication_waiting_)waiting=true;else unsupported=true;
   }
  }
  publication_waiting_=waiting&&!unsupported;
  return !waiting&&!unsupported;
 }
 bool append_receipt(const Item&i,const Basis&b) {
  size_t index=receipts_;
  for(size_t n=0;n<receipts_;++n)if(!receipt_[n].live){index=n;
  break;
  }
  if(index==receipts_){if(receipts_==limit)return false;
  ++receipts_;
  }
  auto&r=receipt_[index];
  r=Receipt{};
  r.item=i;
  r.basis=b;
  r.origin=call_;
  r.promise=requested_promise_;
  r.serial=call_.serial;
  r.kind=call_.kind;
  r.original_receipt=call_.original_receipt;
  r.live=true;
  r.provisional=requested_promise_.birth_receipt!=0;
  return true;
 }
 bool pending_all(bool allow_unconsumed=false) {
  if(!queue(before_)||!all(before_,allow_unconsumed))return false;
  for(unsigned k=0;k<2;++k)if(!deferred(k,before_)||!all(before_,allow_unconsumed))return false;
  return true;
 }
public:
 bool configure(Api api) {
  if(configured_||!api.manager||!api.current||!api.call_origin||!api.retired_output||!api.read||!api.hook_origin||!api.basis||!api.future_producers_closed)return false;
  if((api.provisional_play||api.provisional_current||api.promote)
   &&(!api.provisional_play||!api.provisional_current||!api.promote))return false;
  api_=api;
  configured_=true;
  return true;
 }
 bool copy_handle(uintptr_t address,world::AnimationGraph&out)const {return configured_&&read(address,out);
 }
 bool reject(const char*why){return fail(why);
 }
 const char*error()const{return error_;
 }
 bool waiting_publication()const{return publication_waiting_&&!failed_;
 }
 bool failed()const{return failed_;
 }
 bool active()const{return active_;
 }
 const Call&call()const{return call_;
 }
 // Exact read-only witness for the already-entered actual operation. This
 // grants no producer/output/native callback permission of its own.
 bool current_call(const Call&c)const{return current()&&invoked_&&call_.kind==c.kind&&call_.epoch==c.epoch
  &&call_.serial==c.serial&&call_.source_asset==c.source_asset&&call_.receiver==c.receiver
  &&call_.method==c.method&&call_.original_receipt==c.original_receipt;
 }

 // Call only from the actual selected wrapper BEFORE its original invocation.
 // Existing valid work must already have a concrete earlier producer receipt;
 // taking a snapshot does not promote arbitrary preexisting requests.
 bool begin(Call call) {
  if(!configured_||active_||!call.epoch||!call.serial||!call.source_asset||!call.receiver||!call.method||((call.kind==Kind::rebuild||call.kind==Kind::zero_evaluate||call.kind==Kind::saved_evaluate)&&!call.original_receipt)||call.serial<=last_call_||!api_.call_origin(api_.context,call))return false;
  call_=call;
  last_call_=call.serial;
  failed_=false;
  active_=true;
  invoked_=false;
  native_=collect_=false;
  error_="none";
  publication_waiting_=false;
  if(!current()||!api_.future_producers_closed(api_.context,call_)||!pending_all(true)){active_=false;
  return fail("director_operation_baseline_unowned");
  }
  return true;
 }
 bool invoked(){if(!current()||invoked_)return false;
 invoked_=true;
 return true;
 }
 bool end() {
  const bool ok=current()&&invoked_&&!native_&&!collect_&&pending_all(true);
  active_=invoked_=false;
  if(!ok)return fail("director_operation_delta_unowned");
  return true;
 }
 bool native_begin(Hook hook,uintptr_t manager,uint32_t operation,world::AnimationGraph h,Ticket&out) {
  out={};
  if(!origin(hook,manager)||manager!=api_.manager||!invoked_||native_||collect_||!permitted(operation)
   ||(hook!=Hook::enqueue&&hook!=Hook::append_a&&hook!=Hook::append_b)
   ||(hook==Hook::enqueue&&operation>6)||(hook==Hook::append_a&&operation!=7)||(hook==Hook::append_b&&operation!=8))
   return fail("director_producer_origin_unverified");
  bool valid=false;
  if(!live(h,valid))return fail("director_producer_handle_unreadable");
  requested_basis_=Basis{};
  requested_promise_=Provisional{};
  publication_waiting_=false;
  bool provisional=false;
  if(valid&&operation==0&&(call_.kind==Kind::rebuild||call_.kind==Kind::zero_evaluate||call_.kind==Kind::saved_evaluate)&&api_.provisional_play){
   provisional=api_.provisional_play(api_.context,call_,h,&requested_promise_);
   if(provisional&&(requested_promise_.epoch!=call_.epoch||requested_promise_.source_asset!=call_.source_asset
    ||requested_promise_.original_receipt!=call_.original_receipt||requested_promise_.operation_serial!=call_.serial
    ||requested_promise_.graph.slot!=h.handle||requested_promise_.graph.version!=(h.version&~uint32_t(1))
    ||!requested_promise_.graph.native||!requested_promise_.birth_receipt||!requested_promise_.factory_receipt
    ||!api_.provisional_current(api_.context,requested_promise_)))return fail("director_provisional_play_unverified");
  }
  if(!provisional)requested_promise_=Provisional{};
  if(valid&&!provisional&&!basis(h,operation,requested_basis_))return fail("director_producer_basis_missing");
  if(!(hook==Hook::enqueue?queue(before_):deferred(operation==8,before_)))return fail("director_producer_before_unreadable");
  if(!all(before_,true))return fail("director_producer_before_unowned");
  if(sequence_==~uint64_t(0))return fail("director_producer_serial_exhausted");
  native_=true;
  requested_=h;
  requested_operation_=operation;
  native_ticket_={call_.serial,++sequence_,hook};
  out=native_ticket_;
  return true;
 }
 bool native_end(Ticket ticket) {
  if(!current()||!native_||ticket.call!=call_.serial||ticket.sequence!=native_ticket_.sequence||ticket.hook!=native_ticket_.hook)
   return fail("director_producer_ticket_changed");
  native_=false;
  const bool enqueue=ticket.hook==Hook::enqueue;
  if(!(enqueue?queue(after_):deferred(requested_operation_==8,after_)))return fail("director_producer_after_unreadable");
  // A stale deferred handle causes the exact original append to return without
  // mutation. Native enqueue itself always allocates/pushes even stale values.
  bool valid=false;
  if(!live(requested_,valid))return fail("director_producer_handle_changed");
  if(!enqueue&&!valid&&before_.count==after_.count){
   if(before_.queue!=after_.queue||before_.tag!=after_.tag)return fail("director_stale_append_header_changed");
   for(size_t k=0;k<before_.count;++k)if(!same(before_.item[k],after_.item[k]))return fail("director_stale_append_changed");
   return true;
  }
  if(after_.count!=before_.count+1)return fail("director_producer_delta_unverified");
  if(enqueue){
   if(before_.queue!=after_.queue||(api_.tagged_queue&&(before_.tag==~uint64_t(0)||after_.tag!=before_.tag+1)))return fail("director_queue_concurrent_change");
   for(size_t k=0;k<before_.count;++k)if(!same(before_.item[k],after_.item[k+1]))return fail("director_queue_delta_unverified");
   auto&i=after_.item[0];
   if(i.next!=before_.head||!handle(i.handle,requested_)||i.operation!=requested_operation_)return fail("director_queue_delta_unverified");
   if(valid&&!append_receipt(i,requested_basis_))return fail("director_receipts_exhausted");
  }else{
   for(size_t k=0;k<before_.count;++k){
    if(!handle(before_.item[k].handle,after_.item[k].handle)||before_.item[k].operation!=after_.item[k].operation)return fail("director_deferred_delta_unverified");
    if(auto*r=find(before_.item[k]))r->item=after_.item[k];
   }
   auto&i=after_.item[before_.count];
   if(!handle(i.handle,requested_)||i.operation!=requested_operation_)return fail("director_deferred_delta_unverified");
   if(valid&&!append_receipt(i,requested_basis_))return fail("director_receipts_exhausted");
  }
  return current()&&all(after_,true);
 }
 // Registry authorization adapter. Exact current record address + payload is
 // mandatory, preventing a single graph/op receipt from authorizing duplicates.
 bool authorization(const world::DirectorPending&p,world::DirectorAuthorization&out) {
  publication_waiting_=false;
  if(!configured_||failed_||!api_.current(api_.context,call_))return false;
  Item item{};
  item.address=p.record;
  item.operation=p.operation;
  if(p.operation<7){uint32_t operation=0;
  if(!read(item.address,item.next)||!read(item.address+8,item.handle.handle)||!read(item.address+16,item.handle.version)||!read(item.address+24,operation)||operation!=p.operation)return false;
  }
  else if(!read(item.address,item.handle))return false;
  if(!authorized(item))return false;
  auto*r=find(item);
  if(!r)return false;
  const auto&b=r->basis;
  if(b.graph.native!=p.graph.native||b.graph.slot!=p.graph.slot||b.graph.version!=p.graph.version)return false;
  out={b.graph.native,b.graph.slot,b.source_asset,b.graph.version,p.operation,b.epoch,r->serial};
  return true;
 }
 // Exact destructor-only proof. Does not call an invalid old public handle,
 // and does not grant normal category callbacks or native Audio sampling.
 bool pending_destroy_receipt(uint64_t epoch,uintptr_t native,uintptr_t slot,uint32_t old_version,
   uint64_t actual_rebuild_receipt,uintptr_t output) {
  if(!configured_||failed_||!epoch||!output||!actual_rebuild_receipt||(old_version&1u)
   ||old_version>(~uint32_t(0))-2||!api_.current(api_.context,call_)||epoch!=call_.epoch||!queue(after_))return false;
  for(size_t k=0;k<after_.count;++k){const auto&i=after_.item[k];
   if(i.operation!=2||i.handle.handle!=slot||(i.handle.version&~uint32_t(1))!=old_version+2)continue;
   auto*r=find(i);
   if(!r||r->kind!=Kind::rebuild||r->original_receipt!=actual_rebuild_receipt||!authorized(i)
    ||r->basis.graph.native!=native||r->basis.epoch!=epoch)continue;
   return api_.retired_output(api_.context,epoch,native,slot,old_version,actual_rebuild_receipt,output);
  }
  return false;
 }
 bool consumption_closed()const {
  return current()&&invoked_&&!native_&&!collect_&&api_.future_producers_closed(api_.context,call_);
 }
 bool maintenance_closed()const {return call_.kind==Kind::maintenance&&consumption_closed();
 }
 bool deferred_closed()const {
  if(call_.kind==Kind::maintenance)return maintenance_closed();
  return call_.kind==Kind::native_phase&&api_.frame_deferred_current&&consumption_closed()
   &&api_.frame_deferred_current(api_.context,call_);
 }


 // Called before EACH original collect (including nested16th batch). On false,
 // wrapper invokes exact original TEMPORARY reset and leaves native queue alone.
 bool collect_begin(uintptr_t queue_pointer,Ticket&out) {
  out={};
  publication_waiting_=false;
  if(!origin(Hook::collect,queue_pointer)||!consumption_closed()||!queue(before_)
   ||before_.queue!=queue_pointer)return fail("director_collect_pending_unowned");
  if(!all(before_)){
   if(publication_waiting_){error_="director_fresh_publication_pending";
   return false;
   }
   return fail("director_collect_pending_unowned");
  }
  if(sequence_==~uint64_t(0))return fail("director_producer_serial_exhausted");
  collect_=true;
  native_ticket_={call_.serial,++sequence_,Hook::collect};
  out=native_ticket_;
  return true;
 }
 bool collect_end(Ticket ticket,uintptr_t temporary) {
  if(!current()||!collect_||ticket.call!=call_.serial||ticket.sequence!=native_ticket_.sequence)return fail("director_collect_ticket_changed");
  collect_=false;
  uintptr_t data=0;
  uint64_t count=0,capacity=0;
  if(!read(temporary,data)||!read(temporary+16,count)||!read(temporary+24,capacity)||count!=before_.count||count>(capacity>>1)||!span(data,count,24))return fail("director_collect_concurrent_change");
  for(size_t k=0;k<size_t(count);++k){Item item{};
   if(!read(data+k*24,item.handle)||!read(data+k*24+16,item.operation)||!handle(item.handle,before_.item[k].handle)||item.operation!=before_.item[k].operation)return fail("director_collect_delta_unverified");
  }
  // Old queue nodes have already been freed. Retire copied identities only.
  for(size_t k=0;k<before_.count;++k)if(auto*r=find(before_.item[k]))r->live=false;
  return current();
 }
 bool deferred_begin(unsigned index) {
  if(index>1||!origin(index?Hook::deferred_b:Hook::deferred_a,api_.manager)||!deferred_closed()
   ||!deferred(index,before_)||!all(before_))return fail("director_deferred_pending_unowned");
  return true;
 }
 // Called after actual A/B returned. Source callbacks may append only after a
 // successful native_begin/native_end receipt before the loop reloads count.
 bool deferred_end(unsigned index) {
  if(index>1||!current()||!deferred(index,after_)||after_.count)return fail("director_deferred_not_drained");
  const uint32_t operation=index?8:7;
  for(size_t k=0;k<receipts_;++k)if(receipt_[k].live&&receipt_[k].item.operation==operation)receipt_[k].live=false;
  return true;
 }
 // Must be called on source loss/release before ordinary phase gates detach.
 // Does not read old graph/queue memory or execute pending work.
 void detach(){active_=invoked_=native_=collect_=false;
 receipts_=0;
 call_=Call{};
 }
};
} // namespace mp4_director_maintenance

// END_MP4_DIRECTOR_MAINTENANCE_CORE
// BEGIN_MP4_SCENE_REBUILD_LEDGER
// Receipts are written only around the actual selected original calls. They
// authorize no source mutation and never reinterpret an invalid old handle.
struct Mp4TimelineReceipt {
    void* player=nullptr;void* asset=nullptr;mp4actor::Handle pending{};
    struct Edge{mp4actor::Handle from{},to{};} edges[8]{};
    size_t count=0;bool pending_known=false;
};
struct Mp4RetiringReceipt {
    uintptr_t native=0,slot=0,source_asset=0;uint32_t version=0;
    uint64_t epoch=0,receipt=0;bool invoked=false;
};
struct Mp4RebuildLedger {
    uint64_t epoch=0,sequence=0,transaction=0;void* director=nullptr;void* asset=nullptr;
    Mp4TimelineReceipt actors[32]{};size_t actor_count=0;
    Mp4RetiringReceipt graphs[256]{};size_t graph_count=0,transaction_begin=0;
    bool active=false,evaluation_pending=false;
} mp4_rebuild_ledger;
void* mp4_scene_root_asset_receipt(uint64_t epoch){
    return epoch&&mp4_scene_host.active&&mp4_scene_host.source.generation==epoch
        &&mp4_scene_host.root_asset_handle?mp4_scene_host.root_asset:nullptr;
}
[[maybe_unused]] bool mp4_director_actual_operation(mp4_director_maintenance::Call* out){
    if(!out)return false;
    *out={};const auto& raw=mp4_raw_original_operation;
    if(!game_call()||!raw.depth||!raw.invoked||!raw.epoch||!raw.serial||!raw.receipt
        ||!mp4_scene_host.active||!mp4_scene_source_current()
        ||mp4_scene_host.source.generation!=raw.epoch||!mp4_scene_host.root_asset_handle
        ||reinterpret_cast<uintptr_t>(mp4_scene_host.root_asset)!=raw.root_asset)return false;
    using Kind=mp4_director_maintenance::Kind;
    const auto kind=static_cast<Kind>(raw.kind);
    if(kind!=Kind::play&&kind!=Kind::stop&&kind!=Kind::rebuild&&kind!=Kind::zero_evaluate&&kind!=Kind::saved_evaluate&&kind!=Kind::maintenance
        &&(kind!=Kind::native_phase||!mp4_native_phase_origin(raw.epoch,reinterpret_cast<void*>(raw.director),raw.method)))return false;
    *out={kind,raw.epoch,raw.serial,raw.root_asset,raw.director,raw.method,raw.receipt};
    return true;
}
bool mp4_receipt_same(mp4actor::Handle a,mp4actor::Handle b){return a.handle==b.handle&&a.version==b.version;}
bool mp4_receipt_source(){
    return game_call()&&mp4_scene_host.active&&mp4_scene_source_current()
        &&mp4_rebuild_ledger.epoch==mp4_scene_host.source.generation;
}
bool mp4_receipt_graph(mp4actor::Handle handle,uintptr_t* native,uint32_t* version){
    if(!native||!version||!handle.handle||!mp4_actor_mapped(reinterpret_cast<void*>(handle.handle),0x30,false))return false;
    uint32_t raw=0;uintptr_t pointer=0;
    if(!mp4_actor_field(reinterpret_cast<void*>(handle.handle),0x20,raw)||(raw&1u)||raw!=(handle.version&~1u)
        ||!mp4_actor_field(reinterpret_cast<void*>(handle.handle),mp4_actor_profile.native_graph.node_graph,pointer)||!pointer)return false;
    auto api=mp4_actor_state_api();if(!api.graph_valid(&handle,nullptr))return false;
    *native=pointer;*version=raw;return true;
}
bool mp4_receipt_known_graphs(mp4actor::Handle* out,size_t* count){
    if(!out||!count||!mp4_scene_host.active||!mp4_scene_source_current())return false;
    *count=0;
    const auto add=[&](mp4actor::Handle handle){
        uintptr_t native=0;uint32_t version=0;if(!mp4_receipt_graph(handle,&native,&version))return false;
        for(size_t i=0;i<*count;++i)if(mp4_receipt_same(out[i],handle))return true;
        if(*count==128)return false;out[(*count)++]=handle;return true;
    };
    for(size_t i=0;i<mp4_actor_host.count;++i){
        const auto& owner=mp4_actor_host.owners[i];if(!mp4_actor_owner(nullptr,owner)||!add(owner.graph))return false;
    }
    for(size_t i=0;i<mp4_stage_host.director_count;++i){
        mp4game::PlayableGraph graph{};mp4_api.director_graph_injected(mp4_stage_host.directors[i],&graph,nullptr);
        mp4actor::Handle handle{};std::memcpy(static_cast<void*>(&handle),&graph,sizeof handle);if(!add(handle))return false;
    }
    const auto& source=mp4_scene_host.source;
    if(source.camera_director){
        mp4game::PlayableGraph graph{};mp4_api.director_graph_injected(source.camera_director,&graph,nullptr);
        mp4actor::Handle handle{};std::memcpy(static_cast<void*>(&handle),&graph,sizeof handle);if(!add(handle))return false;
    }
    return true;
}
bool mp4_receipt_actor_players(){
    auto& ledger=mp4_rebuild_ledger;
    for(size_t i=0;i<mp4_actor_host.count;++i){const auto& owner=mp4_actor_host.owners[i];void* player=nullptr;
        if(!mp4_actor_owner(nullptr,owner)||!mp4_actor_field(owner.actor,mp4_actor_profile.fields.actor_player,player)
            ||!mp4_type_is(player,"VL.VLAnimationClipPlayer"))return false;
        size_t index=ledger.actor_count;
        for(size_t k=0;k<ledger.actor_count;++k)if(ledger.actors[k].player==player){index=k;break;}
        if(index==ledger.actor_count){if(index==32)return false;ledger.actors[index].player=player;ledger.actors[index].asset=ledger.asset;++ledger.actor_count;}
        auto& actor=ledger.actors[index];if(actor.asset!=ledger.asset)return false;
        if(!actor.pending_known){
            if(!mp4_actor_field(player,0xc0,actor.pending))return false;
            // A zero source timeline has no old node to remap. A nonzero old
            // node may become invalid only AFTER the controlled original call.
            if(actor.pending.handle){
                auto api=mp4_actor_state_api();
                if(!mp4_actor_mapped(reinterpret_cast<void*>(actor.pending.handle),0x30,false)||!api.playable_valid(&actor.pending,nullptr))return false;
            }
            actor.pending_known=true;
        }
    }
    return true;
}
bool mp4_scene_rebuild_receipt_begin(void* director){
    auto& ledger=mp4_rebuild_ledger;const auto& source=mp4_scene_host.source;
    if(!game_call()||!mp4_scene_host.active||!mp4_scene_source_current()||director!=source.director
        ||!idoly_mp4_runtime::native_clock_scope().held()||!idoly_mp4_runtime::game.automatic_rebuild_in_progress())return false;
    if(ledger.epoch!=source.generation){const uint64_t sequence=ledger.sequence;ledger=Mp4RebuildLedger{};ledger.sequence=sequence;ledger.epoch=source.generation;}
    if(ledger.active||ledger.sequence==~uint64_t(0))return false;
    if(ledger.evaluation_pending&&idoly_mp4_runtime::game.automatic_rebuild_phase()!=idoly_mp4_playback::Phase::restoring)return false;
    void* asset=mp4_api.director_get_asset(director,nullptr);
    if(!mp4_type_is(asset,"UnityEngine.Timeline.TimelineAsset")||(ledger.asset&&ledger.asset!=asset))return false;
    ledger.asset=asset;ledger.director=director;ledger.transaction=++ledger.sequence;
    ledger.transaction_begin=ledger.graph_count;
    if(!mp4_receipt_actor_players())return false;
    mp4actor::Handle graphs[128]{};size_t count=0;if(!mp4_receipt_known_graphs(graphs,&count))return false;
    for(size_t i=0;i<count;++i){
        uintptr_t native=0;uint32_t version=0;if(!mp4_receipt_graph(graphs[i],&native,&version))return false;
        bool seen=false;for(size_t k=0;k<ledger.graph_count;++k){const auto& old=ledger.graphs[k];seen|=old.native==native&&old.slot==graphs[i].handle&&old.version==version;}
        if(seen)continue;if(ledger.graph_count==256)return false;
        ledger.graphs[ledger.graph_count++]={native,graphs[i].handle,reinterpret_cast<uintptr_t>(asset),version,ledger.epoch,ledger.transaction,false};
    }
    ledger.active=true;return true;
}
void mp4_scene_rebuild_receipt_invoked(){
    auto& ledger=mp4_rebuild_ledger;
    if(ledger.active)for(size_t i=ledger.transaction_begin;i<ledger.graph_count;++i)ledger.graphs[i].invoked=true;
}
bool mp4_scene_timeline_receipt_observe(bool completed){
    auto& ledger=mp4_rebuild_ledger;
    if(!mp4_receipt_source()||!ledger.asset||mp4_api.director_get_asset(ledger.director,nullptr)!=ledger.asset)return false;
    for(size_t i=0;i<ledger.actor_count;++i){auto& actor=ledger.actors[i];mp4actor::Handle current{};
        if(!mp4_actor_field(actor.player,0xc0,current))return false;
        bool valid=false;
        if(current.handle&&mp4_actor_mapped(reinterpret_cast<void*>(current.handle),0x30,false)){
            auto api=mp4_actor_state_api();valid=api.playable_valid(&current,nullptr);
        }
        if(valid&&actor.pending_known&&!mp4_receipt_same(actor.pending,current)){
            if(actor.pending.handle){
                if(actor.count==8)return false;
                for(size_t k=0;k<actor.count;++k)if(mp4_receipt_same(actor.edges[k].from,actor.pending)&&!mp4_receipt_same(actor.edges[k].to,current))return false;
                actor.edges[actor.count++]={actor.pending,current};
            }
            actor.pending=current;
        }
        if(completed){actor.pending_known=false;actor.pending={};}
    }
    if(completed)ledger.evaluation_pending=false;
    return true;
}
bool mp4_scene_rebuild_receipt_end(){
    auto& ledger=mp4_rebuild_ledger;if(!ledger.active)return false;
    ledger.active=false;ledger.evaluation_pending=true;return mp4_scene_timeline_receipt_observe(false);
}
bool mp4_scene_evaluate_receipt_begin(void* director){
    auto& ledger=mp4_rebuild_ledger;
    const auto phase=idoly_mp4_runtime::game.automatic_rebuild_phase();
    return mp4_receipt_source()&&!ledger.active&&ledger.evaluation_pending&&director==ledger.director
        &&(phase==idoly_mp4_playback::Phase::starting||phase==idoly_mp4_playback::Phase::restoring)
        &&idoly_mp4_runtime::native_clock_scope().held()&&mp4_receipt_actor_players();
}
[[maybe_unused]] bool mp4_temporal_timeline_rebuilt(uint64_t epoch,void* player,void* asset,mp4actor::Handle source,mp4actor::Handle current){
    const auto& ledger=mp4_rebuild_ledger;
    if(!mp4_receipt_source()||epoch!=ledger.epoch||asset!=ledger.asset||!player||ledger.active)return false;
    mp4actor::Handle actual{};if(!mp4_actor_field(player,0xc0,actual)||!mp4_receipt_same(actual,current))return false;
    for(size_t i=0;i<ledger.actor_count;++i){const auto& actor=ledger.actors[i];if(actor.player!=player||actor.asset!=asset)continue;
        mp4actor::Handle cursor=source;
        for(size_t step=0;step<=actor.count;++step){
            if(mp4_receipt_same(cursor,current))return true;
            bool found=false;for(size_t k=0;k<actor.count;++k)if(mp4_receipt_same(actor.edges[k].from,cursor)){cursor=actor.edges[k].to;found=true;break;}
            if(!found)return false;
        }
    }
    return false;
}
[[maybe_unused]] bool mp4_scene_retired_graph_basis(uintptr_t native,uintptr_t slot,uint32_t current_version,uint32_t* version,uint64_t* epoch,uint64_t* receipt,uintptr_t* asset){
    if(!version||!epoch||!receipt||!asset||!mp4_receipt_source())return false;
    for(size_t i=0;i<mp4_rebuild_ledger.graph_count;++i){const auto& graph=mp4_rebuild_ledger.graphs[i];
        if(graph.invoked&&graph.native==native&&graph.slot==slot&&graph.version<=0xfffffffdu&&graph.version+2==current_version){*version=graph.version;*epoch=graph.epoch;*receipt=graph.receipt;*asset=graph.source_asset;return true;}
    }
    return false;
}
