struct Mp4AudioEvaluationReceipt {
    uint64_t epoch = 0, transaction = 0;
    void *director = nullptr;
    double time = 0;
    bool restoring = false, entered = false, completed = false, consumed = false;
} mp4_audio_evaluation_receipt;
[[maybe_unused]] bool mp4_audio_trusted_rebuild_begin(uint64_t epoch, void *director, bool restoring,
                                                      uint64_t *out) {
    if (!out)
        return false;
    *out = 0;
    const auto &ledger = mp4_rebuild_ledger;
    const auto phase = idoly_mp4_runtime::game.automatic_rebuild_phase();
    if (!game_call() || !mp4_audio_outer_current() || !mp4_scene_host.active || !mp4_scene_source_current() ||
        !ledger.active || ledger.epoch != epoch || epoch != mp4_audio_outer.epoch || !ledger.transaction ||
        ledger.director != director || director != mp4_audio_outer.witness.director ||
        !idoly_mp4_runtime::game.automatic_rebuild_in_progress() ||
        !idoly_mp4_runtime::native_clock_scope().held() ||
        (restoring ? phase != idoly_mp4_playback::Phase::restoring
                   : phase != idoly_mp4_playback::Phase::starting))
        return false;
    mp4_audio_evaluation_receipt = {};
    *out = ledger.transaction;
    return true;
}
[[maybe_unused]] bool mp4_audio_trusted_rebuild_invoked(uint64_t epoch, uint64_t receipt, uintptr_t native,
                                                        uintptr_t slot, uint32_t version) {
    const auto &ledger = mp4_rebuild_ledger;
    if (!game_call() || !mp4_audio_outer_current() || ledger.epoch != epoch || ledger.transaction != receipt)
        return false;
    for (size_t i = ledger.transaction_begin; i < ledger.graph_count; ++i) {
        const auto &old = ledger.graphs[i];
        if (old.invoked && old.epoch == epoch && old.receipt == receipt && old.native == native &&
            old.slot == slot && old.version == version)
            return true;
    }
    return false;
}
// Begin/complete are called INSIDE the actual Mp4OriginalEvaluationScope,
// directly before/after its one successful raw Evaluate call. An exception
// leaves completed=false. after_evaluate consumes the completed receipt once.
[[maybe_unused]] bool mp4_audio_outer_evaluation_begin(void *director, bool restoring) {
    if (!mp4_audio_outer_storage)
        return true;

    auto &receipt = mp4_audio_evaluation_receipt;
    const auto &h = mp4_audio_outer;
    const auto &ledger = mp4_rebuild_ledger;
    const auto phase = idoly_mp4_runtime::game.automatic_rebuild_phase();
    if (!h.epoch)
        return true;
    if (!mp4_audio_outer_current() || receipt.entered || ledger.active || !ledger.evaluation_pending ||
        ledger.epoch != h.epoch || ledger.transaction != h.transaction || director != ledger.director ||
        director != h.witness.director || mp4_volume_original_evaluate_epoch != h.epoch ||
        mp4_volume_original_evaluate_depth != 1 || !idoly_mp4_runtime::native_clock_scope().held() ||
        (restoring ? phase != idoly_mp4_playback::Phase::restoring
                   : phase != idoly_mp4_playback::Phase::starting))
        return false;
    const double time = mp4_api.director_get_time(director, nullptr);
    if (!std::isfinite(time) || (restoring ? std::fabs(time - h.source_time) > 1e-7 : time != 0))
        return false;
    receipt = {h.epoch, h.transaction, director, time, restoring, true, false, false};
    return true;
}
[[maybe_unused]] bool mp4_audio_outer_evaluation_completed(void *director) {
    if (!mp4_audio_outer_storage)
        return true;

    auto &r = mp4_audio_evaluation_receipt;
    const auto &h = mp4_audio_outer;
    if (!h.epoch)
        return true;
    if (!mp4_audio_outer_current() || !r.entered || r.completed || r.consumed || r.epoch != h.epoch ||
        r.transaction != h.transaction || r.director != director ||
        mp4_volume_original_evaluate_epoch != h.epoch || mp4_volume_original_evaluate_depth != 1)
        return false;
    const double time = mp4_api.director_get_time(director, nullptr);
    if (!std::isfinite(time) || std::fabs(time - r.time) > 1e-7)
        return false;
    r.completed = true;
    return true;
}
[[maybe_unused]] bool mp4_audio_trusted_evaluate(uint64_t epoch, bool restoring, double time) {
    auto &r = mp4_audio_evaluation_receipt;
    const auto &ledger = mp4_rebuild_ledger;
    if (!mp4_audio_outer_current() || !r.entered || !r.completed || r.consumed || r.epoch != epoch ||
        r.restoring != restoring || r.transaction != mp4_audio_outer.transaction || ledger.epoch != epoch ||
        ledger.transaction != r.transaction || ledger.active || ledger.evaluation_pending ||
        !std::isfinite(time) || std::fabs(time - r.time) > 1e-7)
        return false;
    r.consumed = true;
    return true;
}
[[maybe_unused]] bool mp4_audio_outer_after_original_evaluate(bool restoring) {
    if (!mp4_audio_outer_active())
        return true;
    return mp4_audio_outer_after_evaluate(restoring, mp4_audio_evaluation_receipt.time);
}
[[maybe_unused]] void *mp4_audio_source_clip(void *source) {
    using Get = void *(*)(void *, Method *);
    return mp4_camera_host.verified ? mp4_cam_call<Get>(mp4_cam_profile.audio_clip)(source, nullptr)
                                    : reinterpret_cast<void *>(1);
}
[[maybe_unused]] bool mp4_audio_outer_camera_source_supported(const Mp4SceneWitness &w, void *source,
                                                              bool playing, bool paused) {
    if (!game_call() || !source || mp4_audio_source_clip(source) ||
        !idoly_mp4_runtime::game.selected_audio_output(source))
        return false;
    if (mp4_audio_outer_active()) {
        auto &h = mp4_audio_outer;
        if (!mp4_audio_outer_current() || !mp4_scene_same_source(w, h.witness) || !mp4_audio_outer_channels())
            return false;
        for (size_t i = 0; i < h.source_count; ++i)
            if (h.sources[i].managed == source)
                return h.sources[i].playing == playing && h.sources[i].paused == paused;
        return false;
    }
    if (!mp4_audio_outer_admit(w))
        return false;
    uintptr_t native = 0;
    uint8_t flag = 0;
    using Playing = bool (*)(void *);
    return mp4_actor_field(source, 16, native) && native &&
           mp4_actor_field(reinterpret_cast<void *>(native), 0x3ac, flag) && flag <= 1 &&
           bool(flag) == paused &&
           reinterpret_cast<Playing>(mp4_native_base + mp4_audio_channel_pins.playing.rva)(
               reinterpret_cast<void *>(native)) == playing;
}
[[maybe_unused]] bool mp4_audio_outer_camera_logical(void *, void *source, bool playing, bool paused) {
    return mp4_audio_outer_logical_source(source, playing, paused);
}

