    pthread_mutex_lock(&idoly_mp4_runtime::control_mutex);
    const bool paused=idoly_mp4_runtime::requested_pause_reason!=IDMP4_PAUSE_NONE;
    pthread_mutex_unlock(&idoly_mp4_runtime::control_mutex);
