using Mp4RenderCamera=void(*)(Mp4RenderContext,void*,Method*);
bool mp4_fresh_staged_camera(void*);
bool mp4_fresh_render_call(Mp4RenderCamera,Mp4RenderContext,void*,Method*);
Mp4RenderCamera mp4_render_stack_original=nullptr,mp4_render_camera_original=nullptr;
Mp4SceneResult (*mp4_camera_begin_extra_draw)(uint64_t*)=nullptr;
bool (*mp4_camera_end_extra_draw)(uint64_t)=nullptr;
bool (*mp4_camera_suspend_extra_render)(uint64_t*)=nullptr;
bool (*mp4_camera_resume_extra_render)(uint64_t)=nullptr;
unsigned mp4_owned_render_depth=0;void* mp4_owned_render_camera=nullptr;
Mp4RenderSubmission mp4_owned_render_submission{};
unsigned mp4_owned_render_submits=0;bool mp4_owned_render_submission_failed=false,mp4_owned_render_ticket_active=false;
void mp4_camera_withdraw_render_ticket() noexcept {
    // Keep the old depth/readers and their finally duties. Only publication
    // is revoked, so a reused Context cannot acknowledge a new source Submit.
    mp4_owned_render_ticket_active=false;
}
VoidMethod mp4_context_submit_original=nullptr;
void mp4_context_submit_hook(void* context_pointer,Method* method){
    Mp4RenderContext context{};
    const bool owned=game_call()&&mp4_owned_render_ticket_active&&context_pointer
        &&mp4_actor_field(context_pointer,0,context)&&context.pointer==mp4_owned_render_submission.context.pointer;
    const bool monitor=game_call()&&mp4_render_hold_has_manual_context();
    if(monitor&&!context.pointer&&context_pointer)(void)mp4_actor_field(context_pointer,0,context);
    const auto submission=mp4_owned_render_submission;
    try{mp4_context_submit_original(context_pointer,method);}
    catch(...){
        if(monitor)mp4_render_hold_context_submit(context,false);
        if(owned){mp4_owned_render_submission_failed=true;
            if(mp4_camera_submit_failed)try{mp4_camera_submit_failed(submission);}catch(...){}
        }
        throw;
    }
    if(monitor)mp4_render_hold_context_submit(context,true);
    if(owned){
        bool recorded=false;
        try{recorded=mp4_camera_record_submit&&mp4_camera_record_submit(submission);}catch(...){recorded=false;}
        if(recorded)++mp4_owned_render_submits;
        else {
            mp4_owned_render_submission_failed=true;
            // An earlier matching Submit/fence does not cover a later failed
            // observer. Conservatively retain this draw's GPU resources.
            if(mp4_camera_submit_failed)try{mp4_camera_submit_failed(submission);}catch(...){}
        }
    }
}

// BEGIN_MP4_UNOWNED_RENDER_HOST
unsigned mp4_unowned_render_depth=0;
void mp4_particle_render_mutation_observe()noexcept;
void mp4_particle_render_observed(Mp4RenderCamera original,Mp4RenderContext context,void*camera,Method*method){
 Mp4RenderHoldOriginal hold;
 if(!hold.enter(original,context,camera)){mp4_camera_host.invalidated=true;mp4_camera_host.error="render_hold_original_unclosed";return;}
 struct Exit{~Exit(){mp4_particle_render_mutation_observe();}}exit;
 mp4_particle_render_mutation_observe();original(context,camera,method);hold.returned();
}
// Ordinary cameras execute with their ambient globals/RNG, including when an
// original selected renderer nests their draw on the same context. Their
// Submit cannot acknowledge the selected camera's suspended draw ticket.
void mp4_unowned_render_call(Mp4RenderCamera original,Mp4RenderContext context,void* camera,Method* method){
    struct Exit {
        idoly_mp4_actor::RandomSuspension random{};Mp4ShaderSuspension shader{};
        Mp4RenderSubmission submission{};uint64_t extra=0;bool ticket=false,failed=false;
        ~Exit() noexcept {
            bool good=!failed;
            try{if(random.active)good=mp4_actor_mono_gate.resume_rng_after_unowned(random)&&good;}catch(...){good=false;}
            try{if(shader.active)good=mp4_shader_resume_after_unowned(shader)&&good;}catch(...){good=false;}
            try{if(extra)good=mp4_camera_resume_extra_render&&mp4_camera_resume_extra_render(extra)&&good;}catch(...){good=false;}
            auto& host=mp4_camera_host;
            if(!good){host.invalidated=true;host.error="camera_unowned_draw_globals_restore_failed";}
            --mp4_unowned_render_depth;
            if(ticket&&!host.invalidated&&mp4_owned_render_depth
                &&mp4_owned_render_submission.source_generation==submission.source_generation
                &&mp4_owned_render_submission.job_generation==submission.job_generation
                &&mp4_owned_render_submission.draw_token==submission.draw_token)
                mp4_owned_render_ticket_active=true;
        }
    } exit;
    exit.ticket=mp4_owned_render_ticket_active;exit.submission=mp4_owned_render_submission;
    mp4_owned_render_ticket_active=false;
    const bool outer_unowned=mp4_unowned_render_depth++==0;
    try{
        if(outer_unowned&&mp4_camera_suspend_extra_render){
            if(!mp4_camera_resume_extra_render||!mp4_camera_suspend_extra_render(&exit.extra))exit.failed=true;
        }else if(outer_unowned&&mp4_owned_render_depth)exit.failed=true;
        if(!mp4_shader_suspend_for_unowned(exit.shader))exit.failed=true;
        if(!mp4_actor_mono_gate.suspend_rng_for_unowned(exit.random))exit.failed=true;
    }catch(...){exit.failed=true;}
    if(exit.failed){mp4_camera_host.invalidated=true;mp4_camera_host.error="camera_unowned_draw_globals_suspend_failed";}
    // Observation/rollback errors invalidate the export, never suppress or
    // retry an unrelated original render (including its own exception).
    mp4_particle_render_observed(original,context,camera,method);
}
// END_MP4_UNOWNED_RENDER_HOST

void mp4_owned_render_call(Mp4RenderCamera original,Mp4RenderContext context,void* camera,Method* method){
    if(mp4_fresh_staged_camera(camera)||mp4_fresh_render_call(original,context,camera,method))return;
    if(!mp4_camera_interception_published()){
        if(mp4_owned_render_depth)mp4_unowned_render_call(original,context,camera,method);
        else mp4_particle_render_observed(original,context,camera,method);
        return;
    }
    if(!game_call()){
        if(mp4_stage_lease_active.load(std::memory_order_acquire))mp4_stage_foreign_dirty.store(true,std::memory_order_release);
        mp4_particle_render_observed(original,context,camera,method);return;
    }
    auto& host=mp4_camera_host;
    if(!host.scope.active()||camera!=host.source.camera){mp4_unowned_render_call(original,context,camera,method);return;}
    if(!mp4_camera_source_current(nullptr)||!mp4_camera_render_route_admit()){
        host.invalidated=true;host.error="camera_owned_draw_route_changed";return;
    }
    if(mp4_unowned_render_depth){host.invalidated=true;host.error="camera_selected_reentry_from_unowned";return;}
    if(mp4_owned_render_depth){
        if(mp4_owned_render_camera!=camera||context.pointer!=mp4_owned_render_submission.context.pointer){host.invalidated=true;host.error="camera_nested_draw_owner_changed";return;}
        mp4_particle_render_observed(original,context,camera,method);return;
    }
    uint64_t tick=0;const uint64_t prewarm=idoly_mp4_runtime::claim_native_prewarm_render();
    const uint64_t generation=prewarm?prewarm:(host.scope.render_tick(tick)?idoly_mp4_runtime::native_simulation_render_generation(tick):0);
    if(!generation)return;
    struct DrawExit{
        uint64_t generation,tick,motion=0,extra=0;bool preview,success=false,waiting=false,gpu=false;
        Mp4RenderSubmission submission{};
        ~DrawExit(){
            bool closed=true;
            try{
                if(extra&&mp4_camera_end_extra_draw)closed=mp4_camera_end_extra_draw(extra)&&closed;
                else if(!waiting&&mp4_camera_restore_extra_render_globals)mp4_camera_restore_extra_render_globals();
            }catch(...){closed=false;}
            try{
                if(motion)closed=mp4_camera_motion_end_draw(motion)&&closed;
                else if(!waiting)closed=mp4_camera_motion_before_source_change()&&closed;
            }catch(...){closed=false;}
            if(gpu){
                const bool submitted=mp4_owned_render_submits&&!mp4_owned_render_submission_failed;
                try{closed=mp4_camera_end_gpu_draw&&mp4_camera_end_gpu_draw(submission)&&closed;}catch(...){closed=false;}
                success=success&&submitted;
                if(!submitted){mp4_camera_host.invalidated=true;mp4_camera_host.error="camera_draw_submit_unobserved";}
            }
            mp4_owned_render_ticket_active=false;
            --mp4_owned_render_depth;mp4_owned_render_camera=nullptr;
            if(!closed){mp4_camera_host.invalidated=true;mp4_camera_host.error="camera_draw_globals_restore_failed";}
            if(waiting&&closed){
                if(preview)idoly_mp4_runtime::release_native_prewarm_render_claim(generation);
                return;
            }
            if(preview)idoly_mp4_runtime::complete_native_prewarm_render(generation,success&&closed);
            else idoly_mp4_runtime::complete_native_simulation_render(generation,tick,success&&closed);
        }
    } exit{generation,tick,0,0,prewarm!=0,false,false,false,{}};
    ++mp4_owned_render_depth;mp4_owned_render_camera=camera;
    mp4_owned_render_submission={context,host.source.generation,generation,tick,0,prewarm!=0};
    mp4_owned_render_submits=0;mp4_owned_render_submission_failed=false;mp4_owned_render_ticket_active=false;
    if(!mp4_camera_begin_extra_draw||!mp4_camera_end_extra_draw||!mp4_camera_render_history_ready||!mp4_camera_render_history_ready()
        ||!mp4_camera_gpu_preflight||!mp4_camera_begin_gpu_draw||!mp4_camera_record_submit||!mp4_camera_submit_failed||!mp4_camera_end_gpu_draw){
        host.invalidated=true;host.error="camera_render_state_unavailable";return;
    }
    const auto ready=mp4_camera_gpu_preflight(host.source.generation,generation);
    if(ready==Mp4SceneResult::waiting){exit.waiting=true;return;}
    if(ready!=Mp4SceneResult::ok){host.invalidated=true;host.error="camera_previous_gpu_draw_unretired";return;}
    Mp4RenderHoldFrame actual_frame;
    if(!actual_frame.enter(host.source.generation,generation,tick,prewarm!=0,context,camera)||!mp4_monitor_camera_pump){
        host.invalidated=true;host.error="camera_monitor_refresh_origin_unavailable";return;
    }
    const auto monitor_ready=mp4_monitor_camera_pump(actual_frame.origin);
    if(monitor_ready==Mp4SceneResult::waiting){exit.waiting=true;return;}
    if(monitor_ready!=Mp4SceneResult::ok){host.invalidated=true;host.error="camera_monitor_refresh_failed";return;}
    const auto extra=mp4_camera_begin_extra_draw(&exit.extra);
    if(extra==Mp4SceneResult::waiting&&!exit.extra){exit.waiting=true;return;}
    if(extra!=Mp4SceneResult::ok||!exit.extra){host.invalidated=true;host.error="camera_render_globals_lease_failed";return;}
    mp4_owned_render_submission.draw_token=exit.extra;exit.submission=mp4_owned_render_submission;
    const auto gpu=mp4_camera_begin_gpu_draw(exit.submission);
    if(gpu==Mp4SceneResult::waiting){exit.waiting=true;return;}
    if(gpu!=Mp4SceneResult::ok){host.invalidated=true;host.error="camera_gpu_draw_lease_failed";return;}
    exit.gpu=true;
    if(!prewarm&&!host.scope.consume_render_grant()){
        host.invalidated=true;host.error="camera_render_ticket_lost";return;
    }
    exit.motion=mp4_camera_motion_begin_draw();if(!exit.motion){host.invalidated=true;host.error="camera_motion_draw_lease_failed";return;}
    mp4_owned_render_ticket_active=true;
    const auto action=[&]{mp4_particle_render_observed(original,context,camera,method);};
    const bool isolated=prewarm?mp4_actor_mono_gate.isolate_preview(action)
        :mp4_actor_mono_gate.isolate_render(reinterpret_cast<uintptr_t>(camera),action);
    exit.success=isolated&&mp4_camera_source_current(nullptr);
    if(!exit.success){host.invalidated=true;host.error="camera_render_rng_ownership_lost";}
}
// BEGIN_MP4_PROFLARE_GPU_OWNER_HOST
// This is the physical draw/upload owner, not Data membership. The Stage
// original Try/Initialize/returned-Data journal independently proves that the
// exact Data belongs to this operation, including before its first upload.
bool mp4_proflare_gpu_current(const Mp4ProFlareGpuOwner&owner){
 if(!game_call()||!owner.source||!owner.job||!owner.draw_sequence||!owner.draw_token
  ||!mp4_owned_render_ticket_active||mp4_owned_render_depth!=1||mp4_unowned_render_depth)return false;
 const auto&submission=mp4_owned_render_submission;const auto&gpu=mp4_gpu_fence_host;
 return submission.source_generation==owner.source&&submission.job_generation==owner.job&&submission.draw_token==owner.draw_token
  &&gpu.configured&&!gpu.sealed&&gpu.draw&&gpu.source==owner.source&&gpu.epoch==owner.job
  &&gpu.sequence==owner.draw_sequence&&gpu.active_token==owner.draw_token;
}
bool mp4_proflare_gpu_origin(uint64_t source,uint64_t job,void*camera,Mp4ProFlareGpuOwner*out){
 if(!out)return false;*out={};
 if(!game_call()||!source||!job||!camera||camera!=mp4_owned_render_camera||!mp4_owned_render_submission.context.pointer)return false;
 const auto&gpu=mp4_gpu_fence_host;Mp4ProFlareGpuOwner owner{source,job,gpu.sequence,mp4_owned_render_submission.draw_token};
 if(!mp4_proflare_gpu_current(owner))return false;*out=owner;return true;
}
bool mp4_proflare_gpu_quiet(const Mp4ProFlareGpuOwner&owner){
 if(!game_call()||!owner.source||!owner.job||!owner.draw_sequence||!owner.draw_token
  ||mp4_owned_render_ticket_active||mp4_owned_render_depth||mp4_unowned_render_depth)return false;
 const auto&render=mp4_gpu_fence_host;const auto&upload=mp4_gpu_auxiliary_host;
 // Only the real Ledger.retire_sequence path advances these retirement
 // counters after physical completion. Do not infer quiet from Submit return,
 // elapsed time, a held clock, or absence of a current draw ticket alone.
 if(!render.configured||render.draw||render.source!=owner.source||render.epoch!=owner.job
  ||render.sequence<owner.draw_sequence||render.last_token<owner.draw_token||render.retired!=render.sequence)return false;
 if(upload.draw)return false;
 if(upload.configured&&(upload.source!=owner.source||upload.epoch!=owner.job||upload.retired!=upload.sequence))return false;
 // No source/Unity object is inspected here; retirement may follow a source
 // handoff. Dispose and list removal must precede final GPU-host finish/reset.
 return true;
}
// END_MP4_PROFLARE_GPU_OWNER_HOST

void mp4_render_stack_hook(Mp4RenderContext context,void* camera,Method* method){mp4_render_hold_automatic(Mp4RenderHoldKind::stack,mp4_render_stack_original,context,camera,method);}
void mp4_render_camera_hook(Mp4RenderContext context,void* camera,Method* method){mp4_render_hold_automatic(Mp4RenderHoldKind::single,mp4_render_camera_original,context,camera,method);}
using Mp4VlbDraw=void(*)(void*,void*,void*,void*,Method*);
Mp4VlbDraw mp4_vlb_draw_original=nullptr;
enum class Mp4VlbDispatch:uint8_t{forward,skip,owned};
Mp4VlbDispatch (*mp4_vlb_begin)(void*,void*,void*,void*)=nullptr;
void (*mp4_vlb_end)(void*,bool)=nullptr;
void (*mp4_vlb_observe)(void*,void*,void*,void*)=nullptr;
void (*mp4_vlb_invalidate)(void*,void*)=nullptr;
void mp4_vlb_draw_hook(void* self,void* commands,void* camera_data,void* material,Method* method){
    const bool on_thread=game_call();
    const bool intercept=mp4_stage_hooks_intercept(on_thread);
    const auto decision=intercept&&mp4_vlb_begin?mp4_vlb_begin(self,commands,camera_data,material):Mp4VlbDispatch::forward;
    if(decision==Mp4VlbDispatch::skip)return;
    struct Exit{void* self;bool owned,completed=false;~Exit(){if(owned&&mp4_vlb_end)mp4_vlb_end(self,completed);}} exit{self,decision==Mp4VlbDispatch::owned,false};
    if(on_thread&&mp4_vlb_invalidate)mp4_vlb_invalidate(self,camera_data);
    mp4_vlb_draw_original(self,commands,camera_data,material,method);exit.completed=true;
    if(on_thread&&mp4_vlb_observe)mp4_vlb_observe(self,commands,camera_data,material);
}

