mp4camp::Binding mp4_volume_callback_pin(const mp4actor::ActorBinding &p) {
  mp4camp::Binding b{};
  b.rva = p.rva;
  std::memcpy(b.prefix, p.prefix, 16);
  return b;
}
void *mp4_volume_callback_class(const mp4actor::ActorBinding &p,
                                const char *name) {
  return mp4_volume_factory_class(mp4_volume_callback_pin(p), name);
}
bool mp4_volume_callback_code(const mp4actor::ActorBinding &p) {
  return mp4_volume_factory_prefix(mp4_volume_callback_pin(p));
}
bool mp4_volume_ctor_code_closed() {
  if (!game_call() || !mp4_source_verified || !mp4_actor_source_verified)
    return false;
  for (const auto &segment : mp4_volume_ctor_segments) {
    if (!segment.count || (segment.count & 3u) ||
        segment.rva > ~uintptr_t(0) - image_base ||
        !mp4_mapped(image_base + segment.rva, segment.count, true))
      return false;
    for (size_t at = 0; at < segment.count; at += 4) {
      const uintptr_t rva = segment.rva + at;
      const auto *current = reinterpret_cast<const uint8_t *>(image_base + rva);
      if (!std::memcmp(current, segment.bytes + at, 4))
        continue;
      // A folded original leaf can be an already source-verified own alias.
      // Require the exact live patched/trampoline receipt, then compare its
      // saved ORIGINAL instruction; arbitrary third-party patches reject.
      bool own = false;
      // Source bytes may straddle a merged CFG segment boundary. Build only
      // the exact original 16-byte entry witness that a known installed alias
      // attests; never accept a branch merely because it resembles a hook.
      for (uintptr_t delta = 0; delta <= 12 && delta <= rva; delta += 4) {
        mp4game::Binding pin{};
        pin.rva = rva - delta;
        bool complete = true;
        for (size_t byte = 0; byte < 16; ++byte) {
          bool found = false;
          for (const auto &original : mp4_volume_ctor_segments)
            if (pin.rva + byte >= original.rva &&
                pin.rva + byte - original.rva < original.count) {
              pin.prefix[byte] = original.bytes[pin.rva + byte - original.rva];
              found = true;
              break;
            }
          if (!found) {
            complete = false;
            break;
          }
        }
        if (complete && mp4_hook_was_statically_verified(pin))
          own = true;
      }
      if (!own)
        return false;
    }
  }
  return true;
}
