    return false;
  const void *method = font_method(lookup, name, argc);
  uintptr_t entry = 0;
  void *owner = nullptr;
  uint8_t count = 255;
  if (!method || !mp4_actor_field(const_cast<void *>(method), 0, entry) ||
      entry != image_base + pin.rva ||
      !mp4_actor_field(const_cast<void *>(method), 32, owner) ||
      owner != declaring ||
      !mp4_actor_field(const_cast<void *>(method), 82, count) || count != argc)
    return false;
