// Caller supplies the actual existing source singleton; this does not invoke
// a lazy VolumeManager.get_instance while claiming read-only source admission.
[[maybe_unused]] bool mp4_volume_assembly_capture(void *manager) {
  auto &h = mp4_volume_assembly;
  if (h.configured || h.manager_root || h.additional_root || !game_call() ||
      !manager || !mp4_camera_motion_source(&h.additional) ||
      !mp4_stage_owner(nullptr))
    return false;
  h.source = mp4_camera_host.source;
  h.job = idoly_mp4_runtime::job.generation;
  if (!h.job)
    return false;
  h.manager = manager;
  h.manager_class = mp4_volume_factory_class(
      mp4_volume_assembly_pins.manager, "UnityEngine.Rendering.VolumeManager");
  h.additional_class = mp4_volume_factory_class(
      mp4_volume_assembly_pins.additional,
      "UnityEngine.Rendering.Universal.UniversalAdditionalCameraData");
  if (object_class(manager) != h.manager_class ||
      object_class(h.additional) != h.additional_class)
    return false;
  h.manager_root = mp4_retain(manager);
  h.additional_root = mp4_retain(h.additional);
  h.configured = true;
  if (!mp4_volume_assembly_raw_roots() || !mp4_volume_assembly_routes(nullptr))
    return false;
  for (size_t n = 0; n < 8; ++n)
    if (!mp4_volume_assembly_field(
            manager, mp4_volume_assembly_manager_names[n],
            mp4_volume_assembly_manager_offsets[n], true, h.fields[n]))
      return false;
  if (!mp4_volume_assembly_field(h.additional, "m_VolumeStack", 120, true,
                                 h.fields[8]) ||
      !mp4_volume_assembly_field(h.additional,
                                 "m_VolumeFrameworkUpdateModeOption", 72, false,
                                 h.fields[9]))
    return false;
  h.fields_ready = true;
  mp4_volume_factory_hooks = {
      mp4_volume_assembly_factory_current,
      mp4_volume_component_callbacks_closed, mp4_volume_assembly_draw_fenced,
      mp4_volume_assembly_final_fenced, mp4_volume_assembly_withdrawn};
  // Actual authored targets/logical callback history precede Mono and Source
  // image capture; all are readonly before any private preparation/Rebuild.
  h.world_duty=true;
  if(!mp4_world_volume_capture())return false;
  // Provider baselines precede Source input capture and ALL private prepares.
  h.renderer_duty = true;
  if (!mp4_renderer_capture())
    return false;
  h.mono_duty = true;
  if (!mp4_volume_mono_host_admit(manager) || !mp4_volume_mono_host_capture())
    return false;
  h.cine_duty = true;
  if (!mp4_cine_capture())
    return false;
  h.source_duty = true;
  if (!mp4_source_volume_prepare(h.source.generation, manager) ||
      mp4_source_volume_capture() != idoly_mp4_volume_source::Result::ok||!mp4_world_volume_complete_source_capture())
    return false;
  h.captured = true;

  h.factory_duty = true;
  if (!mp4_volume_factory_configure(h.source.generation, manager))
    return false;
  h.scope_duty = true;
  if (!h.scope.configure(mp4_volume_assembly_api(), h.source.generation,
                         manager, h.additional))
    return false;
  return true;
}
[[maybe_unused]] bool mp4_volume_assembly_prepare_private() {
  auto &h = mp4_volume_assembly;
  if (!h.captured || h.prepared ||
      !mp4_volume_assembly_current(nullptr, h.source.generation) ||
      mp4_source_volume_scope.validate() != idoly_mp4_volume_source::Result::ok)
    return false;
  h.prepare_started = true;
  if (mp4_renderer_prepare() != mp4cam::Result::ok)
    return false;
  h.prepared = mp4_volume_mono_scope.prepare() == mp4vm::Result::ok;
  return h.prepared;
}
[[maybe_unused]] Mp4SceneResult mp4_volume_assembly_begin(uint64_t *token) {
  auto &h = mp4_volume_assembly;
  if (token)
    *token = 0;
  if (!token || !h.prepared || h.orphaned || h.draw_guard ||
      !mp4_volume_assembly_current(nullptr, h.source.generation))
    return Mp4SceneResult::stale;
  if (mp4_source_volume_scope.validate_inputs() !=
      idoly_mp4_volume_source::Result::ok)
    return Mp4SceneResult::stale;
  h.renderer_token = mp4_renderer_begin_draw();
  if (!h.renderer_token)
    return Mp4SceneResult::stale;
  h.draw_guard = true;
  const auto result = h.scope.begin_draw(token);
  if (result != mp4pv::Result::ok) {
    h.draw_guard = false;
    const bool closed = mp4_renderer_end_draw(h.renderer_token);
    h.renderer_token = 0;
    if (!closed)
      return Mp4SceneResult::stale;
    return result == mp4pv::Result::waiting ? Mp4SceneResult::waiting
                                            : Mp4SceneResult::failed;
  }
  h.token = *token;
  return Mp4SceneResult::ok;
}
[[maybe_unused]] bool mp4_volume_assembly_end(uint64_t token) {
  auto &h = mp4_volume_assembly;
  if (!token || token != h.token)
    return false;
  const bool result = h.scope.end_draw(token);
  h.draw_guard = false;
  const bool renderer =
      h.renderer_token && mp4_renderer_end_draw(h.renderer_token);
  h.renderer_token = 0;
  return result && renderer;
}
[[maybe_unused]] bool mp4_volume_assembly_suspend(uint64_t *token) {
  auto &h = mp4_volume_assembly;
  if (!token)
    return false;
  *token = 0;
  if (!h.scope.active())
    return true;
  if (!h.draw_guard || !h.token || !h.scope.suspend(h.token))
    return false;
  *token = h.token;
  return true;
}
[[maybe_unused]] bool mp4_volume_assembly_resume(uint64_t token) {
  auto &h = mp4_volume_assembly;
  if (!token)
    return true;
  return token == h.token && h.scope.suspended() &&
         mp4_source_volume_scope.validate_inputs() ==
             idoly_mp4_volume_source::Result::ok &&
         h.scope.resume(token);
}
[[maybe_unused]] Mp4SceneResult
mp4_volume_assembly_gpu_begin(const Mp4RenderSubmission &s) {
  auto &h = mp4_volume_assembly;
  if (!h.draw_guard || s.source_generation != h.source.generation ||
      !s.draw_token || s.draw_token != h.token)
    return Mp4SceneResult::stale;
  const auto result = mp4_gpu_begin_draw(s);
  if (result != Mp4SceneResult::ok)
    return result;
  h.receipt = {s.source_generation,
               s.job_generation,
               s.draw_token,
               mp4_volume_factory_host.sequence,
               true,
               false,
               false,
               false};
  return result;
}
[[maybe_unused]] bool
mp4_volume_assembly_gpu_submit(const Mp4RenderSubmission &s) {
  auto &h = mp4_volume_assembly;
  auto &r = h.receipt;
  if (!r.begun || r.source != s.source_generation ||
      r.job != s.job_generation || r.token != s.draw_token || r.ended)
    return false;
  if (!mp4_gpu_record_submit(s))
    return false;
  r.submitted = true;
  return true;
}
[[maybe_unused]] bool
mp4_volume_assembly_gpu_end(const Mp4RenderSubmission &s) {
  auto &r = mp4_volume_assembly.receipt;
  if (!r.begun || r.source != s.source_generation ||
      r.job != s.job_generation || r.token != s.draw_token || r.ended)
    return false;
  const bool result = mp4_gpu_end_draw(s);
  r.ended = true;
  return result;
}
[[maybe_unused]] bool mp4_volume_assembly_before_source_change() {
  auto &h = mp4_volume_assembly;
  if (h.withdrawn)
    return true; // actual once-only handoff receipt, no old writes
  if (h.withdrawal_attempted || h.orphaned)
    return false;
  h.withdrawal_attempted = true;
  bool root = true, renderer = true, cine = true, mono = true;
  // Attempt every domain even if another throws; this is the PRE-original
  // handoff, and must never be retried after a same-pointer replacement Init.
  try {
    root = !h.scope_duty || h.scope.before_source_change();
  } catch (...) {
    root = false;
  }
  try {
    renderer = !h.renderer_duty || mp4_renderer_before_source_change();
  } catch (...) {
    renderer = false;
  }
  try {
    cine = !h.cine_duty || mp4_cine_before_source_change();
  } catch (...) {
    cine = false;
  }
  try {
    mono = !mp4_volume_mono_host.captured ||
           mp4_volume_mono_scope.raw_source_handoff();
  } catch (...) {
    mono = false;
  }
  h.draw_guard = false;
  h.withdrawn = root && renderer && cine && mono && h.scope.globals_withdrawn();
  return h.withdrawn;
}
[[maybe_unused]] void mp4_volume_assembly_abandon() noexcept {
  auto &h = mp4_volume_assembly;
  h.orphaned = true;
  h.draw_guard = false;
  h.scope.abandon_globals();
  if (h.renderer_duty)
    mp4_renderer_abandon_globals();
  if (h.cine_duty)
    mp4_cine_abandon_globals();
  if (mp4_volume_mono_host.captured)
    mp4_volume_mono_scope.abandon();
  mp4_source_volume_publish_interception(false);
}
// Exact original-call receipts; neither a pending transaction nor a merely
// active export authorizes a source lifecycle mutation.
bool mp4_volume_assembly_lifecycle(uint64_t epoch, void *component,
                                   mp4vm::Phase phase) {
  auto &h = mp4_volume_assembly;
  if ((phase != mp4vm::Phase::enable && phase != mp4vm::Phase::disable) ||
      !h.prepared || !mp4_volume_assembly_current(nullptr, epoch))
    return false;
  bool owner = false;
  for (size_t n = 0; n < mp4_volume_mono_host.count; ++n)
    owner |= mp4_volume_mono_host.owners[n].component == component;
  if (!owner)
    return false;
  const auto &ledger = mp4_rebuild_ledger;
  bool rebuild = false;
  if (ledger.active && ledger.epoch == epoch &&
      ledger.director == h.source.director &&
      ledger.asset == mp4_api.director_get_asset(h.source.director, nullptr))
    for (size_t n = ledger.transaction_begin; n < ledger.graph_count; ++n)
      rebuild |= ledger.graphs[n].invoked &&
                 ledger.graphs[n].receipt == ledger.transaction;
  const bool evaluate = mp4_volume_original_evaluate_depth &&
                        mp4_volume_original_evaluate_epoch == epoch;
  const bool native = mp4_volume_mono_scope.granted(epoch) &&
                      mp4_animation_gate.granted_inflight(epoch);
  return rebuild || evaluate || native;
}
bool mp4_volume_assembly_unowned_lifecycle(const mp4vm::Owner &o,
                                           const mp4vm::SourceRefs &) {
  auto &h = mp4_volume_assembly;
  if (o.epoch != h.source.generation || !game_call())
    return false;
  // Existing runtime observer performs scalar revoke + raw global withdrawal
  // before invalidating this exact selected player. It never waits for GPU.
  idoly_mp4_runtime::observe_source_will_change(h.source.player);
  return h.scope.globals_withdrawn() &&
         mp4_volume_mono_scope.raw_source_handoff();
}
bool mp4_volume_assembly_mono_withdrawn(uint64_t epoch) {
  const auto &h = mp4_volume_assembly;
  return epoch == h.source.generation &&
         mp4_volume_assembly_withdrawn(epoch,
                                       mp4_volume_factory_host.published);
}
[[maybe_unused]] bool mp4_volume_assembly_prepare_step(uint64_t tick) {
  auto &h = mp4_volume_assembly;
  return tick != ~uint64_t(0) && h.prepared &&
         mp4_volume_assembly_current(nullptr, h.source.generation) &&
         mp4_volume_mono_scope.prepare_grant(h.source.generation, tick + 1);
}
[[maybe_unused]] bool mp4_volume_assembly_grant(uint64_t tick) {
  auto &h = mp4_volume_assembly;
  if (tick == ~uint64_t(0) ||
      !mp4_volume_assembly_current(nullptr, h.source.generation))
    return false;
  return mp4_volume_mono_scope.grant(h.source.generation, tick + 1) &&
         mp4_source_volume_grant(h.source.generation, tick);
}
[[maybe_unused]] bool mp4_volume_assembly_complete_step(uint64_t tick) {
  auto &h = mp4_volume_assembly;
  return tick != ~uint64_t(0) &&
         mp4_volume_mono_scope.complete_grant(h.source.generation, tick + 1);
}
[[maybe_unused]] void mp4_volume_assembly_hold() noexcept {
  // Cached scalar epochs only. Safe before every owner check and on abort.
  mp4_volume_mono_scope.revoke_grants(mp4_volume_mono_host.source.generation);
  mp4_source_volume_hold(mp4_source_volume_host.epoch);
}
[[maybe_unused]] Mp4SceneResult mp4_volume_assembly_restore_source() {
  auto &h = mp4_volume_assembly;
  mp4_volume_assembly_hold();
  if (!h.captured)
    return Mp4SceneResult::invalid;
  if (!mp4_volume_assembly_current(nullptr, h.source.generation))
    return Mp4SceneResult::stale;
  if (!h.scope.before_source_change())
    return Mp4SceneResult::stale;
  if (!mp4_volume_assembly_final_fenced(h.source.generation))
    return Mp4SceneResult::waiting;
  if (mp4_renderer_restore() != mp4cam::Result::ok ||
      !mp4_renderer_verify_restored())
    return Mp4SceneResult::stale;
  if (!mp4_cine_restore())
    return Mp4SceneResult::stale;
  if (mp4_volume_mono_scope.restore() != mp4vm::Result::ok)
    return Mp4SceneResult::stale;
  const auto world=mp4_world_volume_restore();if(world!=Mp4SceneResult::ok)return world;
  const auto result = mp4_source_volume_scope.restore();
  if (result == idoly_mp4_volume_source::Result::waiting)
    return Mp4SceneResult::waiting;
  if (result != idoly_mp4_volume_source::Result::ok)
    return Mp4SceneResult::stale;
  h.source_verified =
      mp4_source_volume_scope.verify() == idoly_mp4_volume_source::Result::ok;
  return h.source_verified ? Mp4SceneResult::ok : Mp4SceneResult::stale;
}
[[maybe_unused]] Mp4SceneResult mp4_volume_assembly_cleanup(bool owned) {
  auto &h = mp4_volume_assembly;
  mp4_volume_assembly_hold();
  if (owned && !h.source_verified)
    return Mp4SceneResult::waiting;
  // Global detachment is already separate; these resource fences need no old
  // selected-scene lookup and can finish while a replacement source runs.
  if (!mp4_volume_assembly_final_fenced(h.source.generation))
    return Mp4SceneResult::waiting;
  if (h.scope_duty) {
    const auto retired = h.scope.cleanup();
    if (retired == mp4pv::Result::waiting)
      return Mp4SceneResult::waiting;
    if (retired != mp4pv::Result::ok)
      return Mp4SceneResult::stale;
    h.scope_duty = false;
  }
  if (h.factory_duty) {
    if (!mp4_volume_factory_finalize())
      return Mp4SceneResult::waiting;
    h.factory_duty = false;
  }
  if (h.mono_duty) {
    const bool released = mp4_volume_mono_host.captured
                              ? mp4_volume_mono_host_release(owned)
                              : mp4_volume_mono_host_discard_catalog();
    if (!released)
      return Mp4SceneResult::waiting;
    h.mono_duty = false;
  }
  if (h.cine_duty) {
    if (!mp4_cine_cleanup(owned))
      return Mp4SceneResult::waiting;
    h.cine_duty = false;
  }
  if (h.renderer_duty) {
    const auto released = mp4_renderer_release(owned);
    if (released == mp4cam::Result::waiting)
      return Mp4SceneResult::waiting;
    if (released != mp4cam::Result::ok)
      return Mp4SceneResult::stale;
    h.renderer_duty = false;
  }
  if (h.source_duty) {
    mp4_source_volume_drop();
    h.source_duty = false;
  }
  if(h.world_duty){if(!mp4_world_volume_release(owned))return Mp4SceneResult::waiting;h.world_duty=false;}
  if (h.manager_root)
    weak_free(h.manager_root);
  if (h.additional_root)
    weak_free(h.additional_root);
  h.manager_root = h.additional_root = 0;
  h.configured = h.captured = h.prepared = h.source_verified = h.draw_guard =
      h.fields_ready = h.detached = h.prepare_started = h.withdrawal_attempted =
          h.withdrawn = false;
  h.manager = h.additional = h.manager_class = h.additional_class = nullptr;
  h.source = {};
  h.job = h.token = h.renderer_token = 0;
  h.receipt = {};
  for (auto &f : h.fields)
    f = {};
  return Mp4SceneResult::ok;
}

// Idempotent actual prewarm-reset join. No synthetic completed draw receipt.
[[maybe_unused]] Mp4SceneResult mp4_volume_assembly_reset_after_prewarm() {
  auto &h = mp4_volume_assembly;
  if (!h.prepared || h.draw_guard ||
      !mp4_volume_assembly_current(nullptr, h.source.generation))
    return Mp4SceneResult::stale;
  if (!mp4_volume_assembly_prior_draw_fenced(h.source.generation, h.job))
    return Mp4SceneResult::waiting;
  const auto result = mp4_renderer_reset_after_prewarm();
  return result == mp4cam::Result::ok        ? Mp4SceneResult::ok
         : result == mp4cam::Result::waiting ? Mp4SceneResult::waiting
                                             : Mp4SceneResult::stale;
}
// Passive hook installation is distinct from capability/admission. Unknown
// mesh and renderer source-program providers remain mandatory and unmodified.
[[maybe_unused]] void mp4_volume_assembly_install_routes() {
  mp4_cine_cleanup_fence_ready = mp4_volume_assembly_job_fenced;
  mp4_renderer_draw_fence_ready = mp4_volume_assembly_prior_draw_fenced;
  mp4_renderer_final_fence_ready = mp4_volume_assembly_job_fenced;
  mp4_volume_mono_hooks.lifecycle_authorized = mp4_volume_assembly_lifecycle;
  mp4_volume_mono_hooks.before_lifecycle =
      mp4_volume_assembly_unowned_lifecycle;
  mp4_volume_mono_hooks.private_withdrawn_fenced =
      mp4_volume_assembly_mono_withdrawn;
  mp4_mirror_late_route = [](void *p) {
    return mp4_volume_mono_scope.route(mp4vm::Kind::mirror, mp4vm::Phase::late,
                                       p);
  };
  mp4_mirror_parameters_route = [](void *p) {
    return mp4_volume_mono_scope.route(mp4vm::Kind::mirror,
                                       mp4vm::Phase::parameters, p);
  };
  mp4_mirror_destroy_route = [](void *p) {
    return mp4_volume_mono_scope.route(mp4vm::Kind::mirror,
                                       mp4vm::Phase::destroy, p);
  };
  mp4_fog_enable_route = [](void *p) {
    return mp4_volume_mono_scope.route(mp4vm::Kind::height_fog,
                                       mp4vm::Phase::enable, p);
  };
  mp4_fog_disable_route = [](void *p) {
    return mp4_volume_mono_scope.route(mp4vm::Kind::height_fog,
                                       mp4vm::Phase::disable, p);
  };
  mp4_fog_late_route = [](void *p) {
    return mp4_volume_mono_scope.route(mp4vm::Kind::height_fog,
                                       mp4vm::Phase::late, p);
  };
  mp4_light_volume_late_route=[](void*p){return mp4_volume_mono_scope.route(mp4vm::Kind::light,mp4vm::Phase::late,p);};
  mp4_light_volume_destroy_route=[](void*p){return mp4_volume_mono_scope.route(mp4vm::Kind::light,mp4vm::Phase::destroy,p);};
  mp4_cine_apply_enter = mp4_cine_enter_impl;
  mp4_cine_apply_leave = mp4_cine_leave_impl;
  mp4_cine_game_object_before = mp4_cine_game_object_before_impl;
  mp4_cine_volume_before_enable = mp4_cine_volume_before_enable_impl;
  mp4_volume_source_update_owned = mp4_source_volume_owned;
  mp4_volume_source_update_permit = mp4_source_volume_permit;
}

// Logical DETACH -> NATURAL: source restoration already succeeded at Root's
// checkpoint. Do not replay old scalar/profile/pose writes during this step.
// Camera unpublishes its route atomic in the same non-yielding outer operation.
[[maybe_unused]] bool mp4_volume_assembly_detach_natural() noexcept {
  auto &h = mp4_volume_assembly;
  if (!h.source_verified || h.draw_guard || h.renderer_token ||
      !h.scope.globals_withdrawn())
    return false;
  mp4_volume_assembly_hold();
  if (mp4_volume_mono_host.captured)
    mp4_volume_mono_scope.abandon();
  mp4_source_volume_publish_interception(false);
  h.withdrawn = h.withdrawal_attempted = h.detached = true;
  return true;
}

// Detach is independent of deferred GPU disposal and never fabricates a fence.
// After a source-lost observer, only the already recorded raw withdrawal may
// authorize success; no old scalar/profile write is retried on replacement
// Init.
[[maybe_unused]] Mp4SceneResult
mp4_volume_assembly_detach(bool logical_checkpoint) {
  auto &h = mp4_volume_assembly;
  mp4_volume_assembly_hold();
  mp4_source_volume_publish_interception(false);
  if (mp4_volume_mono_host.captured)
    mp4_volume_mono_scope.abandon();
  if (logical_checkpoint) {
    if (mp4_volume_assembly_detach_natural())
      return Mp4SceneResult::ok;
    mp4_volume_assembly_abandon();
    h.detached = true;
    return Mp4SceneResult::stale;
  }
  if (h.detached)
    return h.withdrawn && !h.orphaned ? Mp4SceneResult::ok
                                      : Mp4SceneResult::stale;
  if (h.withdrawn && !h.orphaned) {
    if (mp4_volume_mono_host.captured)
      mp4_volume_mono_scope.abandon();
    h.detached = true;
    return Mp4SceneResult::ok;
  }
  // No prepare and no original draw reached: captures allocated only rooted
  // CPU snapshots/managed containers; nothing was ever published into source.
  const bool unpublished = !h.prepare_started && !h.receipt.begun &&
                           !h.draw_guard && !h.renderer_token &&
                           h.scope.globals_withdrawn();
  if (!h.withdrawal_attempted && !h.orphaned && unpublished) {
    if (mp4_volume_mono_host.captured &&
        !mp4_volume_mono_scope.detach_unpublished()) {
      mp4_volume_assembly_abandon();
      h.detached = true;
      return Mp4SceneResult::stale;
    }
    if (mp4_volume_mono_host.captured)
      mp4_volume_mono_scope.abandon();
    h.withdrawn = h.withdrawal_attempted = h.detached = true;
    return Mp4SceneResult::ok;
  }
  if (!h.withdrawal_attempted && !h.orphaned) {
    Mp4SceneWitness now{};
    // Only an exact still-current generation allows a first raw withdrawal.
    // Invalidation/new Init changes that epoch even if every pointer is reused.
    if (game_call() && idoly_mp4_runtime::game.selected_scene_witness(now) &&
        mp4_scene_same_source(h.source, now) &&
        mp4_volume_assembly_before_source_change()) {
      if (mp4_volume_mono_host.captured)
        mp4_volume_mono_scope.abandon();
      h.detached = true;
      return Mp4SceneResult::ok;
    }
  }
  mp4_volume_assembly_abandon();
  h.detached = true;
  return Mp4SceneResult::stale;
}
// Held logical-checkpoint verification only; ordinary NATURAL playback may
// advance after detach, so resource cleanup does not replay this source check.
[[maybe_unused]] bool mp4_volume_assembly_verify_source() {
  return mp4_volume_assembly.source_verified &&
         mp4_source_volume_scope.verify() == mp4vs::Result::ok;
}

[[maybe_unused]] bool mp4_volume_assembly_complete_latest_step() {
  const auto &h = mp4_volume_assembly;
  if (!mp4_volume_mono_host.captured)
    return !h.prepare_started && !h.receipt.begun;
  return mp4_volume_mono_scope.complete_latest_grant(
      mp4_volume_mono_host.source.generation);
}

// END_MP4_VOLUME_ASSEMBLY_HOST

// BEGIN_MP4_SOURCE_BOOTSTRAP_SPLITS_HOST
// Literal source-only split of the EXISTING World.configure body. The real
// aggregate configured bit is set only after this concrete call returns OK.
// No Fixed/Animation gate or full output/maintenance lease is fabricated here.
Mp4SceneResult mp4_world_source_configure_only(void*,const Mp4SceneWitness&source){
 auto&h=mp4_world_host;if(h.scope.active())return Mp4SceneResult::invalid;
 h.source=source;h.epoch=source.generation;h.invalidated=false;h.restoration_verified=false;
 if(!h.scope.configure(mp4_world_api(),&mp4_fixed_gate,&h,h.epoch,
  mp4_native_base+mp4_world_profile.fixed_condition.rva))return Mp4SceneResult::unsupported;
 return Mp4SceneResult::ok;
}
// IMPORTANT: do not call existing World.quiesce in the EARLY source phase:
// it performs full World.capture. Run the actual early source producer barrier
// separately, then preserve the existing full World.quiesce/capture here only
// AFTER the concrete source Control/Node/module/Child images are available.
[[maybe_unused]] Mp4SceneResult mp4_world_full_capture_after_source_images(){return mp4_world_full_quiesce_adopting_source_gates();}

// Readonly Camera resource SOURCE baselines needed by Activation's actual
// Volume lifecycle proof. They do not create a private graph or render. Keep
// the original strict capture implementation; a partial capture never counts
// as an idempotent completed baseline. Its actual cleanup is polled by the
// bootstrap provider before any retry.
bool mp4_camera_source_baselines_capture_or_verify(){
 if(!game_call()||!mp4_stage_owner(nullptr)||!mp4_actor_clock_held(nullptr))return false;
 auto&h=mp4_volume_assembly;
 if(h.prepared||h.prepare_started)return false;
 if(h.captured)return mp4_volume_assembly_current(nullptr,h.source.generation)
  &&mp4_scene_same_source(h.source,mp4_camera_host.source)
  &&h.job==idoly_mp4_runtime::job.generation
  &&mp4_source_volume_host.captured&&mp4_source_volume_scope.validate()==idoly_mp4_volume_source::Result::ok
  &&mp4_volume_mono_host.captured&&mp4_volume_mono_host_current()&&mp4_world_volume_image_current();
 if(h.configured||h.manager_root||h.additional_root)return false;
 void*manager=mp4_volume_existing_manager();
 return manager&&mp4_volume_assembly_capture(manager)
  &&mp4_volume_assembly_current(nullptr,h.source.generation);
}
[[maybe_unused]] Mp4SceneResult mp4_camera_source_baselines_release(){return mp4_volume_assembly_cleanup(false);}
