  const auto *h = mp4_proflare_coordinator;
  if (!h)
    return mp4_proflare_empty_capture_current(out);
  if (!h->captured || !h->serial || !mp4_proflare_ready(h->batch))
    return false;
  *out = h->serial;
  return true;
