bool mp4_fresh_available(void*){
 return game_call()&&mp4_api_installed&&mp4_source_verified&&mp4_replay_verified&&mp4_playback_source_verified
  &&idoly_mp4_runtime::native_clock_available()&&mp4_actor_routes(nullptr)&&mp4_render_hold_frontends()
  &&mp4_capture_pass_original&&mp4_end_camera_original&&mp4_shader_set_original&&mp4_shader_reset_original
  &&mp4_fresh_listener_current(nullptr)&&mp4_fresh_video_callbacks_ready()&&mp4_fresh_play_frontends_ready();
}
Mp4FreshResult mp4_fresh_admit(void*){
 if(!mp4_fresh_available(nullptr))return mp4_fresh_fail(Mp4FreshResult::unsupported,"fresh_original_bindings_unavailable");
 idoly_mp4_runtime::FreshFactoryReceipt receipt{};
 if(!idoly_mp4_runtime::fresh_factory_receipt(&receipt)||!receipt.serial||!receipt.identity
  ||receipt.player!=idoly_mp4_runtime::game.selected_player()||receipt.presenter!=idoly_mp4_runtime::game.selected_presenter())
  return mp4_fresh_fail(Mp4FreshResult::waiting,"fresh_original_factory_wait");
 void*timeline=nullptr,*master=nullptr;
 if(!mp4_fresh_field(receipt.player,mp4game::Layout{}.player_director_controller,timeline)
  ||!mp4_fresh_field(timeline,mp4game::Layout{}.controller_master,master)||!mp4_alive(master))return mp4_fresh_fail(Mp4FreshResult::waiting,"fresh_original_start_wait");
 auto&g=mp4_fresh_play_gate;
 if(g.failed)return mp4_fresh_fail(Mp4FreshResult::failed,"fresh_play_staging_failed");
 if(!g.deferred){if(mp4_api.automatic_playback.director_state(master,nullptr)==1)return mp4_fresh_fail(Mp4FreshResult::unsupported,"fresh_autoplay_not_intercepted");return Mp4FreshResult::waiting;}
 if(g.bind_pending&&mp4_fresh_play_gate_bind(false))return g.failed?mp4_fresh_fail(Mp4FreshResult::failed,"fresh_play_staging_failed"):mp4_fresh_fail(Mp4FreshResult::waiting,"fresh_play_staging_bind_wait");
 if(!mp4_fresh_play_gate_current()||g.player!=receipt.player||g.identity!=receipt.identity)return mp4_fresh_fail(Mp4FreshResult::stale,"fresh_play_factory_changed");
 mp4_fresh_host.factory=receipt.serial;return Mp4FreshResult::ok;
}
bool mp4_fresh_complete_handle(void*handle){
 if(!handle||!mp4_actor_mapped(handle,16,true))return false;
 using Complete=void(*)(void*,Method*);reinterpret_cast<Complete>(image_base+mp4_actor_profile.complete.rva)(handle,nullptr);
 uint64_t group=1;int32_t version=1;
 return mp4_actor_field(handle,0,group)&&mp4_actor_field(handle,8,version)&&!group&&!version;
}
bool mp4_fresh_actors_current(){
 auto&h=mp4_fresh_host;void*binder=nullptr,*list=nullptr;void**actors=nullptr;size_t count=0;
 if(!mp4_actor_field(h.source.player,mp4game::Layout{}.player_binder,binder)
  ||!mp4_actor_field(binder,mp4game::Layout{}.binder_actors,list)||!mp4_actor_list(list,&actors,&count,32)||count!=h.actor_count)return false;
 const auto&f=mp4_actor_profile.fields;const auto api=mp4_actor_state_api();
 for(size_t i=0;i<count;++i){const auto&a=h.actors[i];void*value=nullptr,*animation=nullptr;mp4actor::Handle graph{},playable{},output{};
  if(actors[i]!=a.actor||!mp4_actor_field(a.actor,f.actor_player,animation)||!mp4_type_is(animation,"VL.VLAnimationClipPlayer")
   ||!mp4_actor_field(a.actor,f.actor_animator,value)||value!=a.animator
   ||!mp4_actor_field(a.extension,f.extension_rig,value)||value!=a.rig
   ||!mp4_actor_field(a.extension,f.extension_builder,value)||value!=a.builder
   ||!mp4_actor_field(a.builder,f.builder_rig,value)||value!=a.rig
   ||!mp4_actor_field(animation,f.player_graph,graph)||!mp4_actor_same_handle(graph,a.graph)
   ||!mp4_actor_field(a.builder,f.builder_playable,playable)||!mp4_actor_same_handle(playable,a.playable)
   ||!mp4_actor_field(a.builder,f.builder_output,output)||!mp4_actor_same_handle(output,a.output)
   ||!api.graph_valid(&graph,nullptr)||api.output_target(&output,nullptr)!=a.animator)return false;
  int32_t mode=-1;if(!mp4_actor_graph_mode(&graph,&mode)||(mode!=1&&mode!=3))return false;
 }
 return true;
}
// Start gate counters (redroid run 30: the video bank was reached only twice
// in 60 s; which earlier gate returned "waiting" the rest of the time?).
struct Mp4FreshStartGates{uint64_t calls=0,qos=0,render_depth=0,callbacks=0,adopt=0,video=0,logged_at=0;}mp4_fresh_start_gates;
// Unity stops a playing graph when its update mode becomes Manual, and neither
// PlayableGraph.Play nor PlayableDirector.Resume starts it again while Manual
// (redroid runs 46-47: master director Paused, graph not playing at every
// grant, Resume without effect), so restoring the mode alone left the timeline
// at 0 for ever. The hold records which graphs were playing; the grant plays
// those again once their own update mode is back.
bool mp4_fresh_graph_playing(mp4actor::Handle graph){
 using Playing=bool(*)(mp4actor::Handle*,mp4actor::Method*);
 return graph.handle&&mp4_actor_source_verified&&reinterpret_cast<Playing>(image_base+mp4_actor_profile.graph_playing.rva)(&graph,nullptr);
}
bool mp4_fresh_graph_replay(mp4actor::Handle graph,bool was_playing){
 if(!was_playing||!graph.handle||mp4_fresh_graph_playing(graph))return true;
 using Play=void(*)(mp4actor::Handle*,mp4actor::Method*);
 reinterpret_cast<Play>(image_base+mp4_actor_profile.graph_play.rva)(&graph,nullptr);
 return mp4_fresh_graph_playing(graph);
}
Mp4FreshResult mp4_fresh_hold(void*){
 auto&h=mp4_fresh_host;if(!mp4_fresh_current(nullptr)){idoly_mp4_runtime::diagnostic_event("fresh_current","hold_entry_stale_line",uint64_t(mp4_fresh_stale_at));return mp4_fresh_fail(Mp4FreshResult::stale,"fresh_scene_changed");}
 if(h.render_depth){++mp4_fresh_start_gates.render_depth;return Mp4FreshResult::waiting;}
 if(!mp4_actor_mono_gate.callbacks_unwound()){++mp4_fresh_start_gates.callbacks;return Mp4FreshResult::waiting;}
 if(h.mono&&!mp4_actor_mono_gate.hold(h.source.generation))return mp4_fresh_fail(Mp4FreshResult::stale,"fresh_actor_gate_lost");
 if(!mp4_fresh_actors_current())return mp4_fresh_fail(Mp4FreshResult::stale,"fresh_actor_identity_changed");
 for(size_t i=0;i<h.actor_count;++i){auto graph=h.actors[i].graph;int32_t mode=-1;
  if(!mp4_actor_graph_mode(&graph,&mode))return mp4_fresh_fail(Mp4FreshResult::stale,"fresh_actor_graph_mode_invalid");
  if(mode!=3){h.actor_playing[i]=mp4_fresh_graph_playing(graph);mp4_actor_graph_set(&graph,3,nullptr);}
  if(!mp4_actor_graph_mode(&graph,&mode)||mode!=3)return mp4_fresh_fail(Mp4FreshResult::stale,"fresh_actor_graph_hold_failed");}
 h.brain_serial=0;
 // Hold scheduling without generating OnBehaviourPause/Resume every frame.
 // Video and other original ScriptPlayables retain their real playing state.
 for(size_t i=0;i<h.director_count;++i){
  const double time=mp4_api.director_get_time(h.directors[i],nullptr);
  if(!std::isfinite(time)||(h.held&&std::fabs(time-h.director_times[i])>0.000001))return mp4_fresh_fail(Mp4FreshResult::stale,"fresh_owned_director_advanced_while_held");
  if(mp4_api.director_get_asset(h.directors[i],nullptr)&&mp4_api.director_get_mode(h.directors[i],nullptr)!=h.director_modes[i])return mp4_fresh_fail(Mp4FreshResult::unsupported,"fresh_owned_director_clock_changed");
  mp4game::PlayableGraph raw{};mp4_api.director_graph_injected(h.directors[i],&raw,nullptr);
  mp4actor::Handle graph{};std::memcpy(&graph,&raw,16);if(graph.handle&&!mp4_api.graph_valid(&raw,nullptr))graph={};h.director_graphs[i]=graph;
  if(graph.handle&&mp4_api.graph_valid(&raw,nullptr)){int32_t mode=-1;if(!mp4_actor_graph_mode(&graph,&mode)||(mode!=h.director_modes[i]&&mode!=3))return mp4_fresh_fail(Mp4FreshResult::unsupported,"fresh_owned_graph_clock_unsupported");
   if(mode!=3){h.director_playing[i]=mp4_fresh_graph_playing(graph);mp4_actor_graph_set(&graph,3,nullptr);
    if(h.directors[i]==h.source.director&&!h.playing_traced){h.playing_traced=true;
     // frame = playing before the switch to Manual, tick = playing after it.
     idoly_mp4_runtime::diagnostic_event("fresh_hold","master_graph_playing_around_manual",uint64_t(h.director_playing[i]),uint64_t(mp4_fresh_graph_playing(graph)));}}
   mp4game::PlayableGraph after{};mp4_api.director_graph_injected(h.directors[i],&after,nullptr);
   if(!mp4_fresh_current(nullptr)||std::memcmp(&raw,&after,16)||!mp4_actor_graph_mode(&graph,&mode)||mode!=3)return mp4_fresh_fail(Mp4FreshResult::stale,"fresh_owned_graph_hold_failed");}
  h.director_times[i]=time;
 }
 for(size_t i=0;i<h.roster->path_graph_count;++i){auto graph=h.roster->path_graphs[i].graph;int32_t mode=-1;
  if(!mp4_actor_graph_mode(&graph,&mode)||(mode!=1&&mode!=3))return mp4_fresh_fail(Mp4FreshResult::stale,"fresh_path_graph_mode_changed");
  if(mode!=3){h.path_playing[i]=mp4_fresh_graph_playing(graph);mp4_actor_graph_set(&graph,3,nullptr);}
  if(!mp4_actor_graph_mode(&graph,&mode)||mode!=3||!mp4_fresh_current(nullptr))return mp4_fresh_fail(Mp4FreshResult::stale,"fresh_path_graph_hold_failed");}
 h.held=true;
 for(size_t i=0;i<h.actor_count;++i){uintptr_t native=0;
  if(!mp4_actor_field(h.actors[i].animator,16,native)||!native||native+0x238<native
   ||!mp4_fresh_complete_handle(reinterpret_cast<void*>(native+0x238)))return mp4_fresh_fail(Mp4FreshResult::waiting,"fresh_animator_job_wait");
 }
 for(size_t i=0;i<h.callbacks.node_count;++i){auto*object=h.callbacks.nodes[i].object;
  const bool foot=mp4_type_is(object,"VL.VLActorFootShadow");
  if(!foot&&!mp4_type_is(object,"VL.Core.VLActorController"))continue;
  if(!mp4_fresh_complete_handle(static_cast<uint8_t*>(object)+184))return mp4_fresh_fail(Mp4FreshResult::waiting,"fresh_actor_aux_job_wait");
  if(foot){uint8_t scheduled=2;if(!mp4_actor_field(object,180,scheduled)||scheduled>1)return mp4_fresh_fail(Mp4FreshResult::stale,"fresh_foot_job_state_invalid");
   if(scheduled)mp4_actor_foot_apply_original(object,nullptr);
   if(!mp4_actor_field(object,180,scheduled)||scheduled)return mp4_fresh_fail(Mp4FreshResult::waiting,"fresh_foot_apply_wait");}
 }
 if(mp4_fresh_current(nullptr))return Mp4FreshResult::ok;
 idoly_mp4_runtime::diagnostic_event("fresh_current","hold_exit_stale_line",uint64_t(mp4_fresh_stale_at));
 return mp4_fresh_fail(Mp4FreshResult::stale,"fresh_scene_changed");
}
// Elichika-style readiness. Elichika never snapshots a scene the game has not
// visibly run and rendered. Acquire used to snapshot the reloaded MV in the
// same call that released its deferred Play, so every check read pre-first-
// frame state (VideoImage binding, MaterialInfo, camera aspect). Here the MV
// runs zero-delta engine frames at t=0, with the selected camera and brain
// drawing normally, until the game's delayed ResetActorModel has returned, a
// few frames have passed, the camera has drawn at the settled target size and
// its aspect matches that target. Nothing is held or gated yet, and the
// timeline cannot leave 0, so no rewind is needed. Only the delayed reset is
// strict (a late reset would replace actors after the snapshot); draw and
// aspect fall back after a bounded wait with a named trace.
constexpr uint64_t mp4_fresh_warm_frames=10,mp4_fresh_warm_fallback_ms=4000;
Mp4FreshResult mp4_fresh_warm(){
 auto&h=mp4_fresh_host;const auto&g=mp4_fresh_play_gate;const uint64_t now=idoly_mp4_runtime::native_entries;
 if(!h.warming){h.warming=true;h.warm_ready=false;idoly_mp4_runtime::diagnostic_event("fresh_warm","started");}
 if(g.failed)return mp4_fresh_fail(Mp4FreshResult::failed,"fresh_play_staging_failed");
 if(g.reset_required&&!g.reset_returned)return mp4_fresh_fail(Mp4FreshResult::waiting,"fresh_warm_reset_wait");
 if(!h.warm_ready){h.warm_ready=true;h.warm_ready_at=h.warm_size_at=now;h.warm_ready_ms=idoly_mp4_runtime::milliseconds();
  h.warm_draws=h.warm_draws_at_size=0;h.warm_width=h.warm_height=0;}
 // The reload turns the window and resizes the controller target, often
 // after Play; a draw only counts once it was made at the current size.
 int32_t width=0,height=0;const bool sized=mp4_actual_source_geometry(h.source.controller,&width,&height)&&width>0&&height>0;
 if(sized&&(width!=h.warm_width||height!=h.warm_height)){
  h.warm_width=width;h.warm_height=height;h.warm_size_at=now;h.warm_draws_at_size=h.warm_draws;
  idoly_mp4_runtime::diagnostic_event("fresh_warm","target_size",uint64_t(width),uint64_t(height));}
 if(now-h.warm_ready_at<mp4_fresh_warm_frames)return mp4_fresh_fail(Mp4FreshResult::waiting,"fresh_warm_frame_wait");
 const uint64_t ms=idoly_mp4_runtime::milliseconds();
 const bool expired=ms>=h.warm_ready_ms&&ms-h.warm_ready_ms>=mp4_fresh_warm_fallback_ms;
 const bool drawn=h.warm_draws>h.warm_draws_at_size;
 // Without the camera lens API the aspect is not checkable; do not wait for it.
 bool aspect=!sized||!mp4_projection_api_available();
 if(!aspect){void*camera=rt_camera(h.source.controller,nullptr);
  if(camera&&mp4_alive(camera)){const float a=aspect_get_original(camera,nullptr);aspect=std::isfinite(a)&&std::fabs(a-float(width)/float(height))<=.005f;}}
 const bool settled=!sized||now-h.warm_size_at>=mp4_fresh_warm_frames;
 if(!expired){
  if(!drawn)return mp4_fresh_fail(Mp4FreshResult::waiting,"fresh_warm_draw_wait");
  if(!settled||!aspect)return mp4_fresh_fail(Mp4FreshResult::waiting,"fresh_warm_target_wait");
 }
 h.warming=false;h.warmed=true;
 // frame=draws at the settled size, tick=engine frames since the reset.
 idoly_mp4_runtime::diagnostic_event("fresh_warm",!drawn?"observed_without_draw":!settled||!aspect?"observed_target_unsettled":"observed",
  uint64_t(h.warm_draws-h.warm_draws_at_size),now-h.warm_ready_at);
 return Mp4FreshResult::ok;
}
// Acquire's last step. Clears the waits acquire named on the way, so a later
